              title="Thời gian"
              description="Ngày bắt đầu và kết thúc của niên khóa."
            />
            <FieldSetContent variant="section" className="pt-0">
              <div className="grid gap-4 sm:grid-cols-2">
                <Controller
                  name="startDate"
