                  )}
                />
                <Controller
                  name="endDate"
                  control={control}
                  render={({ field }) => (
                    <FormFieldCol label="Ngày kết thúc">
                      <DatePicker
                        id={field.name}
                        value={field.value ?? ""}
                        onChange={(v) => {
                          field.onChange(typeof v === "string" ? v : "")
                          field.onBlur()
                        }}
                        placeholder="Chọn ngày"
