  User,
  CalendarClock,
  CircleDot,
  CircleCheck,
  UserCircle,
  MapPin,
  BookOpen,
  GraduationCap,
  Bell,
  MessageSquare,
  type LucideIcon,
} from "lucide-react";
import { formatDateTime } from "@workspace/api-client";
import type { ContactRequest } from "../_component/types";
import { CONTACT_REQUEST_STATUSES, CONTACT_REQUEST_STATUS_LABELS } from "../_component/types";
import { formatPhoneNumber } from "../_component/utils";
import { cn } from "@ui/lib/utils";

function ContactRequestDetailPageInner() {
  const params = useParams();
  const crudNav = useAdminCrudNavigation("/contact-requests");
  const contactId = params.id as string;
  const contactQuery = useContactRequestDetail(contactId);
  const contact = contactQuery.data as ContactRequest | undefined;
  const updateMutation = useUpdateContactRequest();

  const handleToggleRead = useCallback(() => {
    if (!contact) return;
    updateMutation.mutate({
      id: contactId,
      input: { isRead: !contact.isRead },
    });
  }, [contact, contactId, updateMutation]);

  const handleStatusChange = useCallback((value: string) => {
    updateMutation.mutate({
      id: contactId,
      input: { status: value as ContactRequest["status"] },
    });
  }, [contactId, updateMutation]);

  const handlePriorityChange = useCallback((value: string) => {
    updateMutation.mutate({
      id: contactId,
      input: { priority: value as "HIGH" | "MEDIUM" | "LOW" },
    });
  }, [contactId, updateMutation]);

  if (contactQuery.isLoading) return <AdminPageLoading />;
  if (!contact) return null;

  const parseStructuredContent = (content: string) => {
    const lines = content.split("\n").filter((line) => line.trim());
    const structured: Array<{ key: string; value: string; icon?: LucideIcon }> = [];
    let messageContent = "";

    for (const line of lines) {
      const match = line.match(/^([^:]+):\s*(.+)$/);
      if (match) {
        const [, key, value] = match;
        const iconMap: Record<string, LucideIcon> = {
          "Địa chỉ": MapPin,
          "Chương trình": BookOpen,
          "Ngành": GraduationCap,
          "Đăng ký nhận thông tin tuyển sinh": Bell,
          "Đăng ký tư vấn": Bell,
          "Nội dung": MessageSquare,
        };
        structured.push({
          key: key.trim(),
          value: value.trim(),
          icon: iconMap[key.trim()] || undefined,
        });
      } else {
        messageContent += line + "\n";
      }
    }

    return { structured, messageContent: messageContent.trim() };
  };

  const { structured, messageContent } = parseStructuredContent(
    contact.content || contact.message || "",
  );

  return (
    <AdminPageSection>
      <AdminDetailPageHeader
        title="Chi tiết yêu cầu liên hệ"
        variant="module"
        onBack={() => crudNav.list()}
      />

      <AdminDetailLayout>
        <AdminDetailMain>
          <FieldSet variant="section">
            <FieldSectionLegend
              icon={MessageSquare}
              title="Nội dung yêu cầu"
              description="Thông tin chi tiết về yêu cầu hoặc câu hỏi."
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <FieldSectionField label="Tiêu đề" icon={MessageSquare}>
                <p className="text-base font-semibold">{contact.subject}</p>
              </FieldSectionField>

              {structured.length > 0 && (
                <div className="grid gap-3 md:grid-cols-2">
                  {structured.map((item, idx) => {
                    const Icon = item.icon;
                    return (
                      <div
                        key={idx}
                        className="flex items-start gap-3 rounded-lg border border-border/50 bg-muted/30 p-3"
                      >
                        {Icon && (
                          <Icon className="mt-0.5 size-4 shrink-0 text-primary" aria-hidden />
                        )}
                        <div className="min-w-0 flex-1">
                          <p className="text-xs font-semibold text-muted-foreground">{item.key}</p>
                          <p className="text-sm font-medium">{item.value}</p>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {messageContent && (
                <FieldSectionField label="Nội dung" icon={MessageSquare}>
                  <p className="whitespace-pre-wrap rounded-lg bg-muted/30 p-4 text-sm">
                    {messageContent}
                  </p>
                </FieldSectionField>
              )}
            </FieldSetContent>
          </FieldSet>
        </AdminDetailMain>

        <AdminDetailSidebar>
          <div className="sticky top-2 flex max-h-[calc(100vh-6rem)] flex-col gap-4 overflow-y-auto">
            <FieldSet variant="section">
              <FieldSectionLegend
                icon={User}
                title="Thông tin liên hệ"
                description="Thông tin người gửi yêu cầu."
              />
              <FieldSetContent variant="section" className="space-y-3 pt-0">
                <FieldSectionField label="Tên" icon={User} valueClassName="font-medium">
                  {contact.name}
                </FieldSectionField>
                <FieldSectionField label="Email" icon={Mail} valueClassName="font-mono">
                  {contact.email}
                </FieldSectionField>
                {contact.phone && (
                  <FieldSectionField label="SĐT" icon={Phone} valueClassName="font-mono">
                    {formatPhoneNumber(contact.phone)}
                  </FieldSectionField>
                )}
              </FieldSetContent>
            </FieldSet>

            <FieldSet variant="section">
              <FieldSectionLegend
                icon={CircleDot}
                title="Trạng thái xử lý"
                description="Tình trạng và mức độ ưu tiên của yêu cầu."
              />
              <FieldSetContent variant="section" className="space-y-4 pt-0">
                <div className="grid gap-4 sm:grid-cols-2">
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground">Trạng thái</p>
                    <div className="mt-1.5">
                      <TreePicker
                        value={contact.status}
                        onChange={(v) => v && handleStatusChange(v as string)}
                        options={CONTACT_REQUEST_STATUSES.map((s) => ({
                          value: s,
                          label: CONTACT_REQUEST_STATUS_LABELS[s],
                        }))}
                        placeholder="Chọn trạng thái"
                      />
                    </div>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground">Đã đọc</p>
                    <div className="mt-1.5 flex items-center justify-between rounded-lg border border-border px-3 py-2">
                      <div className="flex items-center gap-1.5">
                        {contact.isRead ? (
                          <CircleCheck className="size-4 text-emerald-600" aria-hidden />
                        ) : (
                          <CircleDot className="size-4 text-muted-foreground" aria-hidden />
                        )}
                        <span
                          className={cn(
                            "text-sm font-medium",
                            contact.isRead ? "text-emerald-600" : "text-muted-foreground",
                          )}
                        >
                          {contact.isRead ? "Đã đọc" : "Chưa đọc"}
                        </span>
                      </div>
                      <Switch
                        checked={contact.isRead}
                        onCheckedChange={handleToggleRead}
                        disabled={updateMutation.isPending}
                      />
                    </div>
                  </div>
                </div>

                <FieldSectionDivider />
                <div>
                  <p className="text-xs font-semibold text-muted-foreground">Ưu tiên</p>
                  <div className="mt-1.5">
                    <TreePicker
                      value={contact.priority || "MEDIUM"}
                      onChange={(v) => v && handlePriorityChange(v as string)}
                      options={[
                        { value: "HIGH", label: "Cao" },
                        { value: "MEDIUM", label: "Trung bình" },
                        { value: "LOW", label: "Thấp" },
                      ]}
                      placeholder="Chọn mức ưu tiên"
                    />
                  </div>
                </div>

                {contact.assignedToName && (
                  <>
                    <FieldSectionDivider />
                    <FieldSectionField label="Người phụ trách" icon={UserCircle} valueClassName="font-medium">
                      {contact.assignedToName}
                    </FieldSectionField>
                  </>
                )}
              </FieldSetContent>
            </FieldSet>

            <FieldSet variant="section">
              <FieldSectionLegend
                icon={CalendarClock}
                title="Thời gian"
                description="Mốc thời gian tạo và cập nhật yêu cầu."
              />
              <FieldSetContent variant="section" className="space-y-3 pt-0">
                <FieldSectionField label="Tạo lúc" icon={CalendarClock}>
                  {formatDateTime(contact.createdAt)}
                </FieldSectionField>
                <FieldSectionField label="Cập nhật lần cuối" icon={CalendarClock}>
                  {formatDateTime(contact.updatedAt)}
                </FieldSectionField>
              </FieldSetContent>
            </FieldSet>
          </div>
        </AdminDetailSidebar>
      </AdminDetailLayout>
    </AdminPageSection>
  );
}

export default function ContactRequestDetailPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin"]}>
      <ContactRequestDetailPageInner />
    </AdminPageGuard>
  );
}

src/app/contact-requests/_component/colu.content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"
import {
  CircleCheck,
  CircleDashed,
  CircleDot,
  Mail,
  MessageSquare,
  Phone,
  User,
} from "lucide-react"
import {
  UsageStatusBadge,
  type UsageStatusTone,
} from "@ui/components/usage-status-badge"
import { defineAdminTrashActionsColumn } from "@ui/components/admin"
import {
  defineDataTableActionsColumn,
  defineLinkedUserColumns,
  resolveLinkedUser,
} from "@ui/components/data-table"
import {
  type AdminTableView,
  buildAdminTableColumns,
  dedupeAdminTableColumns,
  defineAdminCreatedAtColumn,
  defineAdminUpdatedAtColumn,
} from "@/lib/admin-table-columns"
import type { ContactRequest } from "./types"
import {
  CONTACT_REQUEST_PRIORITY_LABELS,
  CONTACT_REQUEST_STATUS_LABELS,
} from "./types"
import { formatPhoneNumber } from "./utils"
import {
  ContactRequestRowActions,
  contactRequestActionsColumnMeta,
} from "./contact-row-actions"

/** Độ rộng cột bảng — khai báo trên `meta.className`, không đặt `min-w` trong cell. */
const COL_NAME = "w-[200px] min-w-[200px] max-w-[260px]"
const COL_EMAIL = "w-[240px] min-w-[240px] max-w-[300px]"
const COL_PHONE = "w-[160px] min-w-[160px] max-w-[250px]"
const COL_SUBJECT = "w-[180px] min-w-[180px] max-w-[250px]"
const COL_TEXT = "w-[250px] min-w-[250px] max-w-[350px]"
const COL_SLUG = "w-[140px] min-w-[120px] max-w-[165px]"
const COL_BADGE = "w-[108px] min-w-[96px] max-w-[120px]"
const COL_DATE = "w-[180px] min-w-[180px] max-w-[185px]"

export interface ContactRequestColumnsProps {
  view?: AdminTableView
  onView: (contact: ContactRequest) => void
  onDelete: (contact: ContactRequest) => void
  onRestore: (contact: ContactRequest) => void
  onPurge: (contact: ContactRequest) => void
  onStatusChange: (
    contact: ContactRequest,
    status: ContactRequest["status"]
  ) => void | Promise<void>
  onSetRead: (contact: ContactRequest, isRead: boolean) => void | Promise<void>
  onSetPriority: (
    contact: ContactRequest,
    priority: NonNullable<ContactRequest["priority"]>
  ) => void | Promise<void>
  busy: boolean
  canUpdate?: boolean
  canDelete?: boolean
  canRestore?: boolean
}

export function getContactRequestColumns(
  props: ContactRequestColumnsProps
): ColumnDef<ContactRequest>[] {
  const {
    view = "list",
    onView,
    onDelete,
    onRestore,
    onPurge,
    onStatusChange,
    onSetRead,
    onSetPriority,
    busy,
    canUpdate,
    canDelete,
    canRestore,
  } = props

  const dataColumns: ColumnDef<ContactRequest>[] = [
    {
      accessorKey: "name",
      header: "Tên",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: {
        filterPlaceholder: "Lọc tên…",
        className: COL_NAME,
      } as ColumnDef<ContactRequest>["meta"],
      cell: ({ row }) => (
        <span className="flex min-w-0 items-center gap-2">
          <User className="size-4 shrink-0 text-primary/80" aria-hidden />
          <span className="font-medium">{row.original.name}</span>
        </span>
      ),
    },
    {
      accessorKey: "email",
      header: "Email",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: {
        filterPlaceholder: "Lọc email…",
        className: COL_EMAIL,
      },
      cell: ({ getValue }) => (
        <span className="flex min-w-0 items-center gap-2 font-mono text-xs text-muted-foreground">
          <Mail className="size-3.5 shrink-0 opacity-80" aria-hidden />
          <span className="break-all">{String(getValue())}</span>
        </span>
      ),
    },
    {
      accessorKey: "phone",
      header: "SĐT",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: {
        filterPlaceholder: "Lọc SĐT…",
        className: COL_PHONE,
      },
      cell: ({ getValue }) => {
        const v = getValue() as string | null | undefined
        return v ? (
          <span className="flex items-center gap-2 font-mono text-xs tabular-nums">
            <Phone
              className="size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
            {formatPhoneNumber(v)}
          </span>
        ) : (
          <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <Phone className="size-3.5 opacity-40" aria-hidden />—
          </span>
        )
      },
    },
    {
      accessorKey: "subject",
      header: "Tiêu đề",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: {
        filterPlaceholder: "Lọc tiêu đề…",
        className: COL_SUBJECT,
      },
      cell: ({ getValue }) => (
        <span className="line-clamp-5">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "content",
      header: "Nội dung",
      cell: ({ row }) => {
        const content = row.original.content || row.original.message || ""

        // Parse structured content to extract only the message
        const lines = content.split("\n").filter((line) => line.trim())
        let message = ""

        for (const line of lines) {
          const match = line.match(/^Nội dung:\s*(.+)$/)
          if (match) {
            message = match[1].trim()
            break
          }
        }

        // If no "Nội dung:" found, use the whole content but exclude structured fields
        if (!message) {
          for (const line of lines) {
            const isStructuredField = line.match(
              /^(Địa chỉ|Chương trình|Ngành|Đăng ký|Số điện thoại|Email):/
            )
            if (!isStructuredField) {
              message += line + " "
            }
          }
        }

        return (
          <span className="flex items-start gap-2 text-xs">
            <MessageSquare
              className="mt-0.5 size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
            <span className="line-clamp-5">{message.trim() || content}</span>
          </span>
        )
      },
      enableColumnFilter: true,
      filterFn: () => true,
      meta: {
        filterPlaceholder: "Lọc nội dung…",
        className: COL_TEXT,
      },
    },
    {
      accessorKey: "address",
      header: "Địa chỉ",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: { className: COL_TEXT },
      cell: ({ row }) => {
        const content = row.original.content || row.original.message || ""
        const match = content.match(/Địa chỉ:\s*(.+?)(?:\n|$)/)
        const address = match ? match[1].trim() : ""

        if (!address)
          return <span className="text-xs text-muted-foreground">—</span>

        return <span className="text-xs">{address}</span>
      },
    },
    {
      accessorKey: "program",
      header: "Chương trình",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: { className: COL_SLUG },
      cell: ({ row }) => {
        const content = row.original.content || row.original.message || ""
        const match = content.match(/Chương trình:\s*(.+?)(?:\n|$)/)
        const program = match ? match[1].trim() : ""

        if (!program)
          return <span className="text-xs text-muted-foreground">—</span>

        return <span className="text-xs">{program}</span>
      },
    },
    {
      accessorKey: "major",
      header: "Ngành",
      enableColumnFilter: true,
      filterFn: () => true,
      meta: { className: COL_SLUG },
      cell: ({ row }) => {
        const content = row.original.content || row.original.message || ""
        const match = content.match(/Ngành:\s*(.+?)(?:\n|$)/)
        const major = match ? match[1].trim() : ""

        if (!major)
          return <span className="text-xs text-muted-foreground">—</span>

        return <span className="text-xs">{major}</span>
      },
    },
    {
      accessorKey: "isRead",
      header: "Đã đọc",
      enableColumnFilter: true,
      enableSorting: false,
      meta: {
        className: COL_BADGE,
        filterVariant: "select",
        filterLabel: "Đã đọc",
        selectOptions: [
          { value: "true", label: "Đã đọc" },
          { value: "false", label: "Chưa đọc" },
        ],
      },
      filterFn: (row, id, v) => {
        if (v == null || v === "") return true
        const read = row.getValue(id) as boolean | undefined
        return String(read) === v
      },
      cell: ({ row }) => {
        const read = row.original.isRead
        return (
          <UsageStatusBadge
            tone={read ? "success" : "warning"}
            className="text-[10px]"
          >
            {read ? "Đã đọc" : "Chưa đọc"}
          </UsageStatusBadge>
        )
      },
    },
    {
      accessorKey: "priority",
      header: "Ưu tiên",
      enableColumnFilter: true,
      enableSorting: false,
      meta: {
        className: COL_BADGE,
        filterVariant: "select",
        filterLabel: "Ưu tiên",
        selectOptions: [
          { value: "HIGH", label: "Cao" },
          { value: "MEDIUM", label: "Trung bình" },
          { value: "LOW", label: "Thấp" },
        ],
      },
      filterFn: (row, id, v) => {
        if (v == null || v === "") return true
        const p = (row.getValue(id) as string | undefined) ?? "MEDIUM"
        return p === v
      },
      cell: ({ getValue }) => {
        const p = (getValue() as ContactRequest["priority"]) ?? "MEDIUM"
        const tone =
          p === "HIGH" ? "danger" : p === "MEDIUM" ? "warning" : "success"
        return (
          <UsageStatusBadge tone={tone} className="text-[10px]">
            {CONTACT_REQUEST_PRIORITY_LABELS[p]}
          </UsageStatusBadge>
        )
      },
    },
    {
      accessorKey: "status",
      header: "Trạng thái",
      cell: ({ row }) => {
        const status = row.original.status
        const label = CONTACT_REQUEST_STATUS_LABELS[status]

        const statusConfig = {
          new: { icon: CircleDot, tone: "warning" as UsageStatusTone },
          "in-progress": {
            icon: CircleDashed,
            tone: "warning" as UsageStatusTone,
          },
          resolved: { icon: CircleCheck, tone: "success" as UsageStatusTone },
          archived: { icon: CircleCheck, tone: "danger" as UsageStatusTone },
        } as const

        const config =
          statusConfig[status as keyof typeof statusConfig] ??
          statusConfig.archived
        const StatusIcon = config.icon

        return (
          <UsageStatusBadge tone={config.tone} className="gap-1.5 text-[10px]">
            <StatusIcon className="size-3 shrink-0" aria-hidden />
            {label}
          </UsageStatusBadge>
        )
      },
      filterFn: (row, id, v) => {
        if (v == null || v === "") return true
        return row.getValue(id) === v
      },
      meta: {
        className: COL_BADGE,
        filterVariant: "select",
        filterLabel: "Trạng thái",
        selectOptions: [
          { value: "new", label: "Mới" },
          { value: "in-progress", label: "Đang xử lý" },
          { value: "resolved", label: "Đã giải quyết" },
          { value: "archived", label: "Đã lưu trữ" },
        ],
      },
    },
    ...defineLinkedUserColumns<ContactRequest>({
      scope: "assignedTo",
      header: "Người phụ trách",
      getUser: (row) =>
        resolveLinkedUser(row.assignedTo, {
          id: row.assignedToId,
          name: row.assignedToName,
          email: row.assignedTo?.email,
        }),
    }),
    ...defineLinkedUserColumns<ContactRequest>({
      scope: "submittedBy",
      header: "Tài khoản gửi",
      getUser: (row) =>
        resolveLinkedUser(row.submittedBy, {
          id: row.submittedById,
          name: row.submittedByName,
          email: row.submittedBy?.email,
        }),
      defaultHidden: true,
    }),
    defineAdminCreatedAtColumn<ContactRequest>({
      header: "Ngày tạo",
      meta: { className: COL_DATE },
    }),
    defineAdminUpdatedAtColumn<ContactRequest>({
      header: "Cập nhật lúc",
      meta: { className: COL_DATE },
    }),
    
  ]

  const listActionsColumn = defineDataTableActionsColumn<ContactRequest>({
    enableColumnFilter: true,
    filterFn: () => true,
    columnMeta: contactRequestActionsColumnMeta,
    cell: ({ row }) => (
      <ContactRequestRowActions
        contact={row.original}
        canUpdate={!!canUpdate}
        canDelete={!!canDelete}
        busy={busy}
        onView={() => onView(row.original)}
        onDelete={canDelete ? () => onDelete(row.original) : undefined}
        onPurge={canDelete ? () => onPurge(row.original) : undefined}
        onStatusChange={(status) => onStatusChange(row.original, status)}
        onSetRead={(isRead) => onSetRead(row.original, isRead)}
        onSetPriority={(priority) => onSetPriority(row.original, priority)}
      />
    ),
  })

  return dedupeAdminTableColumns(
    buildAdminTableColumns({
      view,
      dataColumns,
      listActionsColumn,
      trashActionsColumn: defineAdminTrashActionsColumn<ContactRequest>({
        canWrite: !!(canRestore || canDelete),
        busy,
        pageConfirm: true,
        columnMeta: { className: "sticky right-0" },
        onRestore: canRestore ? onRestore : undefined,
        onPurge: canDelete ? onPurge : undefined,
      }),
    })
  )
}

src/app/contact-requests/_component/cont.content:
import type { ExportFieldDef } from "@ui/lib/build-field-export"
import {
  CONTACT_REQUEST_PRIORITY_LABELS,
  CONTACT_REQUEST_STATUS_LABELS,
} from "./types"
import type { ContactRequest } from "./types"

export function parseContactStructuredContent(
  content: string | undefined,
): Record<string, string> {
  if (!content) return {}
  const parsed: Record<string, string> = {}
  for (const line of content.split("\n").filter((l) => l.trim())) {
    const match = line.match(/^([^:]+):\s*(.+)$/)
    if (match) {
      const [, key, value] = match
      parsed[key.trim()] = value.trim()
    }
  }
  return parsed
}

const ACTIVE_EXPORT_FIELDS: ExportFieldDef<ContactRequest>[] = [
  { header: "Tên", value: (r) => r.name, width: 22 },
  { header: "Email", value: (r) => r.email, width: 28 },
  { header: "Số điện thoại", value: (r) => r.phone, width: 16 },
  { header: "Tiêu đề", value: (r) => r.subject, width: 32, wrap: true },
  {
    header: "Địa chỉ",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")["Địa chỉ"],
    width: 28,
    wrap: true,
  },
  {
    header: "Chương trình",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")[
        "Chương trình"
      ],
    width: 24,
  },
  {
    header: "Ngành",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")["Ngành"],
    width: 20,
  },
  {
    header: "Đăng ký nhận thông tin tuyển sinh",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")[
        "Đăng ký nhận thông tin tuyển sinh"
      ],
    width: 18,
  },
  {
    header: "Đăng ký tư vấn",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")[
        "Đăng ký tư vấn"
      ],
    width: 14,
  },
  {
    header: "Nội dung",
    value: (r) => {
      const parsed = parseContactStructuredContent(r.content || r.message || "")
      return parsed["Nội dung"] || r.content || r.message || ""
    },
    width: 40,
    wrap: true,
  },
  {
    header: "Trạng thái",
    value: (r) => CONTACT_REQUEST_STATUS_LABELS[r.status],
    width: 14,
  },
  {
    header: "Ưu tiên",
    value: (r) =>
      r.priority
        ? CONTACT_REQUEST_PRIORITY_LABELS[r.priority]
        : CONTACT_REQUEST_PRIORITY_LABELS.MEDIUM,
    width: 12,
  },
  { header: "Đã đọc", value: (r) => r.isRead, width: 10 },
  { header: "Người được giao", value: (r) => r.assignedToName, width: 20 },
  { header: "Ngày tạo", value: (r) => r.createdAt, width: 18 },
  { header: "Ngày cập nhật", value: (r) => r.updatedAt, width: 18 },
]

const TRASH_EXPORT_FIELDS: ExportFieldDef<ContactRequest>[] = [
  { header: "Tên", value: (r) => r.name, width: 22 },
  { header: "Email", value: (r) => r.email, width: 28 },
  { header: "Tiêu đề", value: (r) => r.subject, width: 32, wrap: true },
  {
    header: "Địa chỉ",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")["Địa chỉ"],
    width: 28,
    wrap: true,
  },
  {
    header: "Chương trình",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")[
        "Chương trình"
      ],
    width: 24,
  },
  {
    header: "Ngành",
    value: (r) =>
      parseContactStructuredContent(r.content || r.message || "")["Ngành"],
    width: 20,
  },
  {
    header: "Nội dung",
    value: (r) => r.content || r.message || "",
    width: 40,
    wrap: true,
  },
  { header: "Xóa lúc", value: (r) => r.deletedAt, width: 18 },
]

export function getContactRequestExportFields(
  kind: "active" | "trash",
): ExportFieldDef<ContactRequest>[] {
  return kind === "trash" ? TRASH_EXPORT_FIELDS : ACTIVE_EXPORT_FIELDS
}

"use client";

import {
  CircleCheck,
  CircleDashed,
  CircleDot,
  Eye,
  Flag,
  MailOpen,
  Mail,
  Settings2,
  Trash2,
} from "lucide-react";
import {
  DATA_TABLE_ACTIONS_COLUMN_ID,
  DataTableRowActionsMenu,
  TABLE_ACTIONS_COLUMN_META,
  type DataTableRowActionConfirm,
  type DataTableRowActionItem,
} from "@ui/components/data-table";
import {
  UsageStatusBadge,
  type UsageStatusTone,
} from "@ui/components/usage-status-badge";
import type { ContactRequest } from "./types";
import {
  CONTACT_REQUEST_PRIORITIES,
  CONTACT_REQUEST_PRIORITY_LABELS,
  CONTACT_REQUEST_STATUSES,
  CONTACT_REQUEST_STATUS_LABELS,
} from "./types";

const STATUS_VISUAL: Record<
  ContactRequest["status"],
  { icon: typeof CircleDot; tone: UsageStatusTone }
> = {
  new: { icon: CircleDot, tone: "warning" },
  "in-progress": { icon: CircleDashed, tone: "warning" },
  resolved: { icon: CircleCheck, tone: "success" },
  archived: { icon: CircleCheck, tone: "danger" },
};

const PRIORITY_TONE: Record<
  NonNullable<ContactRequest["priority"]>,
  UsageStatusTone
> = {
  HIGH: "danger",
  MEDIUM: "warning",
  LOW: "success",
};

export type ContactRequestRowActionsProps = {
  contact: ContactRequest;
  canUpdate: boolean;
  canDelete: boolean;
  busy?: boolean;
  onView: () => void;
  onDelete?: () => void;
  onPurge?: () => void;
  onStatusChange: (status: ContactRequest["status"]) => void | Promise<void>;
  onSetRead: (isRead: boolean) => void | Promise<void>;
  onSetPriority: (
    priority: NonNullable<ContactRequest["priority"]>,
  ) => void | Promise<void>;
};

function contactDeleteConfirm(contact: ContactRequest): DataTableRowActionConfirm {
  return {
    title: "Đưa yêu cầu vào thùng rác?",
    description: (
      <>
        Yêu cầu từ <strong>{contact.name}</strong> ({contact.email}) sẽ không
        hiển thị trong danh sách. Có thể khôi phục trong tab Thùng rác.
      </>
    ),
    confirmLabel: "Xóa tạm",
    destructive: true,
  };
}

function contactPurgeConfirm(contact: ContactRequest): DataTableRowActionConfirm {
  return {
    title: "Xóa vĩnh viễn yêu cầu?",
    description: (
      <>
        Yêu cầu từ <strong>{contact.name}</strong> ({contact.email}) sẽ bị xoá
        khỏi cơ sở dữ liệu. Không thể hoàn tác.
      </>
    ),
    confirmLabel: "Xóa vĩnh viễn",
    destructive: true,
  };
}

function ContactStatusBadge({ status }: { status: ContactRequest["status"] }) {
  const cfg = STATUS_VISUAL[status];
  const Icon = cfg.icon;
  return (
    <UsageStatusBadge tone={cfg.tone} className="gap-1 text-[10px]">
      <Icon className="size-3 shrink-0" aria-hidden />
      {CONTACT_REQUEST_STATUS_LABELS[status]}
    </UsageStatusBadge>
  );
}

export function ContactRequestRowActions({
  contact,
  canUpdate,
  canDelete,
  busy,
  onView,
  onDelete,
  onPurge,
  onStatusChange,
  onSetRead,
  onSetPriority,
}: ContactRequestRowActionsProps) {
  const actions: DataTableRowActionItem[] = [
    {
      key: "view",
      label: "Xem chi tiết",
      hint: "Mở trang thông tin đầy đủ",
      onClick: onView,
      icon: <Eye />,
      group: "primary",
    },
  ];

  if (canUpdate) {
    for (const status of CONTACT_REQUEST_STATUSES) {
      if (status === contact.status) continue;
      const cfg = STATUS_VISUAL[status];
      const StatusIcon = cfg.icon;
      actions.push({
        key: `status-${status}`,
        label: CONTACT_REQUEST_STATUS_LABELS[status],
        hint: `Chuyển trạng thái sang «${CONTACT_REQUEST_STATUS_LABELS[status]}»`,
        onClick: () => onStatusChange(status),
        icon: <StatusIcon />,
        group: "status",
      });
    }

    actions.push({
      key: "toggle-read",
      label: contact.isRead ? "Đánh dấu chưa đọc" : "Đánh dấu đã đọc",
      hint: contact.isRead
        ? "Hiển thị lại như yêu cầu mới"
        : "Ghi nhận đã xem nội dung",
      onClick: () => onSetRead(!contact.isRead),
      icon: contact.isRead ? <Mail /> : <MailOpen />,
      group: "status",
    });

    const currentPriority = contact.priority ?? "MEDIUM";
    for (const priority of CONTACT_REQUEST_PRIORITIES) {
      if (priority === currentPriority) continue;
      actions.push({
        key: `priority-${priority}`,
        label: `Ưu tiên: ${CONTACT_REQUEST_PRIORITY_LABELS[priority]}`,
        hint: `Đặt mức ưu tiên ${CONTACT_REQUEST_PRIORITY_LABELS[priority].toLowerCase()}`,
        onClick: () => onSetPriority(priority),
        icon: <Flag />,
        group: "status",
      });
    }
  }

  if (canDelete && onDelete) {
    actions.push({
      key: "soft-delete",
      label: "Xóa tạm",
      hint: "Đưa vào thùng rác, có thể khôi phục",
      onClick: onDelete,
      icon: <Trash2 />,
      group: "danger",
      menuVariant: "destructive",
      confirm: contactDeleteConfirm(contact),
    });
  }

  if (canDelete && onPurge) {
    actions.push({
      key: "purge",
      label: "Xóa vĩnh viễn",
      hint: "Xóa khỏi cơ sở dữ liệu, không hoàn tác",
      onClick: onPurge,
      icon: <Trash2 />,
      group: "danger",
      menuVariant: "destructive",
      confirm: contactPurgeConfirm(contact),
    });
  }

  const priority = contact.priority ?? "MEDIUM";

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={busy}
      autoConfirmDangerousActions={false}
      groups={{
        primary: { label: "Thao tác", icon: Settings2 },
        status: {
          label: "Trạng thái & ưu tiên",
          sublabel: true,
          header: (
            <div className="flex flex-wrap items-center gap-1.5 px-1 pb-1">
              <ContactStatusBadge status={contact.status} />
              <UsageStatusBadge
                tone={PRIORITY_TONE[priority]}
                className="text-[10px]"
              >
                {CONTACT_REQUEST_PRIORITY_LABELS[priority]}
              </UsageStatusBadge>
              <UsageStatusBadge
                tone={contact.isRead ? "success" : "warning"}
                className="text-[10px]"
              >
                {contact.isRead ? "Đã đọc" : "Chưa đọc"}
              </UsageStatusBadge>
            </div>
          ),
        },
        danger: { label: "Xóa", sublabel: true },
      }}
    />
  );
}

export const contactRequestActionsColumnMeta = {
  ...TABLE_ACTIONS_COLUMN_META,
  className: `${TABLE_ACTIONS_COLUMN_META.className} sticky right-0 z-[10]`,
};

export const contactRequestActionsColumnId = DATA_TABLE_ACTIONS_COLUMN_ID;

