"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { Badge } from "@ui/components/badge";
import { cn } from "@ui/lib/utils";
import { ArrowRight, GitBranch } from "lucide-react";
import type { EntityRelationRow, EntitySchemaRow } from "./types";
import { DOMAIN_BADGE_CLASS, formatEntityRowCount } from "./utils";

function RefBadges({ tables }: { tables: string[] }) {
  if (!tables.length) {
    return <span className="text-xs text-muted-foreground">—</span>;
  }
  return (
    <div className="flex flex-wrap gap-1">
      {tables.map((table) => (
        <Badge key={table} variant="outline" className="font-mono text-[10px]">
          {table}
        </Badge>
      ))}
    </div>
  );
}

const CARDINALITY_LABEL: Record<EntityRelationRow["cardinality"], string> = {
  "many-to-one": "N:1",
  "one-to-one": "1:1",
  self: "self",
};

export function getEntitySchemaColumns(): ColumnDef<EntitySchemaRow>[] {
  return [
    {
      accessorKey: "tableName",
      header: "Bảng DB",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-sm font-medium">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "entityName",
      header: "Entity",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue())}
        </span>
      ),
    },
    {
      accessorKey: "exportModelName",
      header: "Model export",
      enableColumnFilter: false,
      meta: { defaultHidden: true },
      cell: ({ getValue }) => (
        <span className="font-mono text-xs">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "activeRowCount",
      header: "Bản ghi",
      enableColumnFilter: false,
      size: 100,
      meta: { className: "w-[100px] min-w-[100px] max-w-[120px]" },
      cell: ({ row }) => {
        const { activeRowCount, rowCount, trashedRowCount } = row.original;
        if (activeRowCount < 0) {
          return <span className="text-xs text-muted-foreground">—</span>;
        }
        return (
          <div className="tabular-nums">
            <span className="text-sm font-medium">
              {formatEntityRowCount(activeRowCount)}
            </span>
            {trashedRowCount > 0 ? (
              <p className="text-[10px] text-muted-foreground">
                +{formatEntityRowCount(trashedRowCount)} thùng rác
              </p>
            ) : rowCount !== activeRowCount ? (
              <p className="text-[10px] text-muted-foreground">
                tổng {formatEntityRowCount(rowCount)}
              </p>
            ) : null}
          </div>
        );
      },
    },
    {
      accessorKey: "domain",
      header: "Nhóm",
      enableColumnFilter: false,
      cell: ({ getValue }) => {
        const domain = String(getValue());
        return (
          <Badge
            variant="outline"
            className={cn("text-[10px] font-normal", DOMAIN_BADGE_CLASS[domain])}
          >
            {domain}
          </Badge>
        );
      },
    },
    {
      accessorKey: "columnCount",
      header: "Cột",
      enableColumnFilter: false,
      size: 72,
      meta: { className: "w-[72px] min-w-[72px] max-w-[72px]" },
      cell: ({ row }) => (
        <span className="text-sm tabular-nums text-muted-foreground">
          {row.original.columnCount}
          {row.original.fkCount > 0 ? (
            <span className="text-[10px]"> ({row.original.fkCount} FK)</span>
          ) : null}
        </span>
      ),
    },
    {
      accessorKey: "referencesOut",
      header: "Tham chiếu tới",
      enableColumnFilter: false,
      cell: ({ row }) => <RefBadges tables={row.original.referencesOut} />,
    },
    {
      accessorKey: "referencedBy",
      header: "Được tham chiếu bởi",
      enableColumnFilter: false,
      cell: ({ row }) => <RefBadges tables={row.original.referencedBy} />,
    },
    {
      accessorKey: "description",
      header: "Mô tả",
      enableColumnFilter: false,
      meta: { defaultHidden: true },
      cell: ({ getValue }) => (
        <span className="line-clamp-2 text-xs text-muted-foreground">
          {String(getValue() || "—")}
        </span>
      ),
    },
  ];
}

export function getEntityRelationColumns(): ColumnDef<EntityRelationRow>[] {
  return [
    {
      accessorKey: "fromTable",
      header: "Từ bảng",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-sm">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "fromColumn",
      header: "Cột",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue())}
        </span>
      ),
    },
    {
      id: "arrow",
      header: "",
      enableSorting: false,
      enableColumnFilter: false,
      size: 40,
      meta: { className: "w-10 min-w-10 max-w-10 px-0 text-center" },
      cell: () => <ArrowRight className="mx-auto size-4 text-muted-foreground" />,
    },
    {
      accessorKey: "toTable",
      header: "Đến bảng",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-sm">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "toColumn",
      header: "Cột đích",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue())}
        </span>
      ),
    },
    {
      accessorKey: "cardinality",
      header: "Quan hệ",
      enableColumnFilter: false,
      size: 88,
      cell: ({ getValue }) => {
        const value = getValue() as EntityRelationRow["cardinality"];
        return (
          <Badge variant="secondary" className="gap-1 font-mono text-[10px]">
            <GitBranch className="size-3" />
            {CARDINALITY_LABEL[value]}
          </Badge>
        );
      },
    },
    {
      accessorKey: "deleteRule",
      header: "On delete",
      enableColumnFilter: false,
      meta: { defaultHidden: true },
      cell: ({ getValue }) => {
        const rule = getValue() as string | undefined;
        return rule ? (
          <Badge variant="outline" className="font-mono text-[10px]">
            {rule}
          </Badge>
        ) : (
          <span className="text-xs text-muted-foreground">—</span>
        );
      },
    },
  ];
}

src/app/data/_component/entity-schema-pa.content:
"use client";

import { useMemo, useState } from "react";
import type { ColumnFiltersState } from "@tanstack/react-table";
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert";
import { Badge } from "@ui/components/badge";
import { AdminDataTable } from "@ui/components/data-table";
import {
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs";
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell";
import { GitBranch, Loader2, TableProperties } from "lucide-react";
import {
  getEntityRelationColumns,
  getEntitySchemaColumns,
} from "./columns";
import { useDatabaseSchema } from "./_hooks";
import {
  buildEntityRelationRows,
  buildEntitySchemaRows,
  formatEntityRowCount,
} from "./utils";

export function EntitySchemaPanel() {
  const { schema, loading, error } = useDatabaseSchema(true);
  const [schemaTab, setSchemaTab] = useState<"tables" | "relations">("tables");
  const [globalFilter, setGlobalFilter] = useState("");
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);

  const entityRows = useMemo(
    () => (schema ? buildEntitySchemaRows(schema) : []),
    [schema],
  );
  const relationRows = useMemo(
    () => (schema ? buildEntityRelationRows(schema.relations) : []),
    [schema],
  );

  const entityColumns = useMemo(() => getEntitySchemaColumns(), []);
  const relationColumns = useMemo(() => getEntityRelationColumns(), []);

  return (
    <FieldSet variant="section">
      <FieldSectionLegend
        icon={TableProperties}
        title="Bảng entity (MikroORM)"
        description="Danh sách bảng từ apps/api/src/entities, số bản ghi và quan hệ FK"
        badge={
          schema ? (
            <Badge variant="outline" className="text-xs font-normal">
              {schema.tables.length} bảng · {schema.relations.length} quan hệ ·{" "}
              {formatEntityRowCount(
                schema.totalActiveRows ??
                  schema.tables.reduce(
                    (sum, t) => sum + Math.max(0, t.activeRowCount ?? t.rowCount ?? 0),
                    0,
                  ),
              )}{" "}
              bản ghi
            </Badge>
          ) : undefined
        }
      />
      <FieldSetContent
        variant="section"
        className="space-y-4 px-4 pb-4 pt-0 sm:px-5"
      >
        {loading ? (
          <div className="flex items-center gap-2 py-8 text-sm text-muted-foreground">
            <Loader2 className="size-4 animate-spin" />
            Đang tải metadata entity và đếm bản ghi…
          </div>
        ) : null}

        {error ? (
          <Alert variant="destructive">
            <AlertTitle className="text-sm">Không tải được schema</AlertTitle>
            <AlertDescription className="text-xs">{error}</AlertDescription>
          </Alert>
        ) : null}

        {!loading && !error && schema ? (
          <Tabs value={schemaTab} onValueChange={(v) => setSchemaTab(v as "tables" | "relations")}>
            <TabsList className={ADMIN_LIST_TABS_LIST_CLASS}>
              <TabsTrigger
                value="tables"
                className={ADMIN_LIST_TABS_TRIGGER_CLASS}
              >
                <TableProperties className="size-4" />
                Bảng ({entityRows.length})
              </TabsTrigger>
              <TabsTrigger
                value="relations"
                className={ADMIN_LIST_TABS_TRIGGER_CLASS}
              >
                <GitBranch className="size-4" />
                Quan hệ FK ({relationRows.length})
              </TabsTrigger>
            </TabsList>

            <TabsContent value="tables">
              <AdminDataTable
                tableScope="data-entity-tables"
                data={entityRows}
                getRowId={(row) => row.id}
                columns={entityColumns}
                isLoading={false}
                emptyLabel="Không có bảng entity."
                manualFiltering
                globalFilter={globalFilter}
                onGlobalFilterChange={setGlobalFilter}
                globalFilterPlaceholder="Tìm theo tên bảng, entity, domain…"
                columnFilters={columnFilters}
                onColumnFiltersChange={setColumnFilters}
                showIndexColumn
                showColumnFilters={false}
                footer={
                  <p className="text-xs text-muted-foreground">
                    Nguồn: MikroORM metadata từ{" "}
                    <code className="rounded bg-muted px-1">apps/api/src/entities</code>
                    . &quot;Bản ghi&quot; = số dòng đang hoạt động; bảng có{" "}
                    <code className="rounded bg-muted px-1">deletedAt</code> hiển thị thêm số trong thùng rác.
                    Sắp xếp theo số bản ghi giảm dần.
                  </p>
                }
              />
            </TabsContent>

            <TabsContent value="relations">
              <AdminDataTable
                tableScope="data-entity-relations"
                data={relationRows}
                getRowId={(row) => row.id}
                columns={relationColumns}
                isLoading={false}
                emptyLabel="Không có quan hệ FK."
                manualFiltering
                globalFilter={globalFilter}
                onGlobalFilterChange={setGlobalFilter}
                globalFilterPlaceholder="Tìm theo bảng hoặc cột…"
                columnFilters={columnFilters}
                onColumnFiltersChange={setColumnFilters}
                showIndexColumn
                showColumnFilters={false}
                footer={
                  <p className="text-xs text-muted-foreground">
                    Mỗi dòng là một quan hệ ManyToOne / OneToOne giữa hai entity.
                    Sơ đồ trực quan: menu{" "}
                    <code className="rounded bg-muted px-1">/database-schema</code>.
                  </p>
                }
              />
            </TabsContent>
          </Tabs>
        ) : null}
      </FieldSetContent>
    </FieldSet>
  );
}

