import * as XLSX from "xlsx";

const EXCEL_META_SHEET = "__meta";

function parseCellValue(value: unknown): unknown {
  if (value == null || value === "") return undefined;
  if (value instanceof Date) return value.toISOString();
  return value;
}

/**
 * Parse file .xlsx trên trình duyệt — cùng cấu trúc JSON export/import của API.
 * Tránh upload một file lớn; dữ liệu được import theo lô qua `runChunkedImport`.
 */
export function parseExcelToImportData(
  arrayBuffer: ArrayBuffer,
): Record<string, unknown[]> {
  const workbook = XLSX.read(arrayBuffer, {
    type: "array",
    cellDates: true,
    dense: true,
  });

  const sheetMap = new Map<string, string>();
  const modelNamesFromMeta: string[] = [];
  const metaSheet = workbook.Sheets[EXCEL_META_SHEET];
  if (metaSheet) {
    const metaRows = XLSX.utils.sheet_to_json<(string | number | null)[]>(
      metaSheet,
      { header: 1, defval: null },
    );
    for (let rowIndex = 1; rowIndex < metaRows.length; rowIndex++) {
      const row = metaRows[rowIndex];
      if (!row) continue;
      const modelName = String(row[0] ?? "").trim();
      const sheetName = String(row[1] ?? "").trim();
      const tableName = String(row[2] ?? "").trim();
      if (modelName && sheetName) {
        sheetMap.set(modelName, sheetName);
        modelNamesFromMeta.push(modelName);
        if (tableName) sheetMap.set(tableName, sheetName);
      }
    }
  }

  const data: Record<string, unknown[]> = {};
  const modelNames =
    modelNamesFromMeta.length > 0
      ? modelNamesFromMeta
      : workbook.SheetNames.filter((name) => name !== EXCEL_META_SHEET);

  for (const rawModelName of modelNames) {
    const sheetName = sheetMap.get(rawModelName) ?? rawModelName;
    if (sheetName === EXCEL_META_SHEET) continue;

    const worksheet = workbook.Sheets[sheetName];
    if (!worksheet) continue;

    const matrix = XLSX.utils.sheet_to_json<(string | number | null)[]>(
      worksheet,
      { header: 1, defval: null },
    );
    if (matrix.length === 0) {
      data[rawModelName] = [];
      continue;
    }

    const headerRow = matrix[0] ?? [];
    const headers = headerRow
      .map((value) => String(value ?? "").trim())
      .filter(Boolean);
    if (headers.length === 0) {
      data[rawModelName] = [];
      continue;
    }

    const rows: Record<string, unknown>[] = [];
    for (let rowIndex = 1; rowIndex < matrix.length; rowIndex++) {
      const row = matrix[rowIndex];
      if (!row) continue;

      const record: Record<string, unknown> = {};
      let hasValue = false;

      headers.forEach((header, columnIndex) => {
        const parsed = parseCellValue(row[columnIndex]);
        if (parsed === undefined) return;
        record[header] = parsed;
        hasValue = true;
      });

      if (hasValue) {
        rows.push(record);
      }
    }

    data[rawModelName] = rows;
  }

  return data;
}

src/app/data/_component/import-chunked.t.content:
import type {
  ImportModelProgress,
  ImportProgressState,
} from "../import-progress-panel";
import {
  buildImportJobFailureMessage,
  buildModelImportErrorSummary,
  formatImportErrorMessage,
  type ImportRowError,
} from "./import-error-message";
import {
  createEmptyModelTiming,
  formatImportDuration,
  type ImportJobTimingEntry,
  type ImportModelTimingStats,
} from "./import-timing";

type ApiModelTiming = {
  model: string;
  clearMs: number;
  insertMs: number;
  imported: number;
};

type ApiImportTiming = {
  requestMs: number;
  models: ApiModelTiming[];
};

function applyRowErrorsToModel(
  model: ImportModelProgress,
  modelName: string,
  rowErrors: ImportRowError[],
): ImportModelProgress {
  const { summary, details, fullTitle } = buildModelImportErrorSummary(
    modelName,
    rowErrors,
  );
  if (!summary) return model;
  return {
    ...model,
    status: "error" as const,
    error: summary,
    rowErrorDetails: details,
    errorTitle: fullTitle,
  };
}

export type ImportConfig = {
  modelOrder: string[];
  bundles: Record<string, readonly string[]>;
  rowChunkSize: number;
  /** Kích thước lô riêng (vd. post JSON nhỏ để chạy song song). */
  modelChunkSizes?: Record<string, number>;
  /** Số lô skipClear cùng bảng chạy song song (mặc định 3). */
  parallelChunkConcurrency?: number;
  /** Ghi đè song song theo bảng (vd. post=1 tránh lock DB). */
  modelParallelConcurrency?: Record<string, number>;
};

export type ImportChunkJob = {
  label: string;
  primaryModel: string;
  skipClear: boolean;
  payload: Record<string, unknown[]>;
  recordCount: number;
  bundledModels: string[];
  isLastChunkForModel: boolean;
};

type ApiEnvelope<T> = {
  success: boolean;
  message?: string;
  error?: string | null;
  data?: T;
};

type ImportResultPayload = {
  success?: boolean;
  message?: string;
  rowErrors?: Array<{ model: string; index: number; message: string }>;
  timing?: ApiImportTiming;
};

function nowMs(): number {
  return typeof performance !== "undefined" && typeof performance.now === "function"
    ? performance.now()
    : Date.now();
}

function attachTimingsToModels(
  models: ImportModelProgress[],
  timingByName: Map<string, ImportModelTimingStats>,
): ImportModelProgress[] {
  return models.map((model) => {
    const timing = timingByName.get(model.name);
    return timing ? { ...model, timing: { ...timing } } : model;
  });
}

function touchModelTiming(
  timingByName: Map<string, ImportModelTimingStats>,
  modelName: string,
  records: number,
): ImportModelTimingStats {
  let timing = timingByName.get(modelName);
  if (!timing) {
    timing = createEmptyModelTiming(records);
    timingByName.set(modelName, timing);
  }
  return timing;
}

function markModelImportStart(
  timingByName: Map<string, ImportModelTimingStats>,
  modelName: string,
  records: number,
  atMs: number,
): void {
  const timing = touchModelTiming(timingByName, modelName, records);
  if (timing.startedAtMs == null) {
    timing.startedAtMs = atMs;
  }
}

function markModelImportEnd(
  timingByName: Map<string, ImportModelTimingStats>,
  modelName: string,
  records: number,
  atMs: number,
): void {
  const timing = touchModelTiming(timingByName, modelName, records);
  timing.completedAtMs = atMs;
  if (timing.startedAtMs != null) {
    timing.wallMs = Math.max(0, timing.completedAtMs - timing.startedAtMs);
  }
}

function applyServerTimings(
  timingByName: Map<string, ImportModelTimingStats>,
  models: ImportModelProgress[],
  serverTimings?: ApiModelTiming[],
): void {
  if (!serverTimings?.length) return;
  for (const entry of serverTimings) {
    const model = models.find((m) => m.name === entry.model);
    const timing = touchModelTiming(
      timingByName,
      entry.model,
      model?.records ?? entry.imported,
    );
    timing.serverClearMs += entry.clearMs;
    timing.serverInsertMs += entry.insertMs;
  }
}

function addHttpJobDuration(
  timingByName: Map<string, ImportModelTimingStats>,
  models: ImportModelProgress[],
  modelNames: string[],
  httpMs: number,
): void {
  for (const name of modelNames) {
    const model = models.find((m) => m.name === name);
    const timing = touchModelTiming(
      timingByName,
      name,
      model?.records ?? 0,
    );
    timing.httpMs += httpMs;
    timing.httpJobCount += 1;
  }
}

function chunkArray<T>(items: T[], size: number): T[][] {
  if (items.length <= size) return [items];
  const chunks: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    chunks.push(items.slice(i, i + size));
  }
  return chunks;
}

/** Khớp `orderModelsForDependencySafeImport` trên API. */
export function orderModelsForImport(
  keys: string[],
  modelOrder: string[],
): string[] {
  const set = new Set(keys);
  const out: string[] = [];
  const take = (model: string) => {
    if (set.has(model)) {
      out.push(model);
      set.delete(model);
    }
  };

  take("role");
  take("user");
  take("userRole");
  for (const model of [...modelOrder].reverse()) {
    take(model);
  }
  for (const model of set) {
    out.push(model);
  }
  return out;
}

export function buildChunkedImportJobs(
  data: Record<string, unknown[]>,
  config: ImportConfig,
): ImportChunkJob[] {
  const keys = Object.keys(data).filter(
    (key) => Array.isArray(data[key]) && data[key].length > 0,
  );
  if (keys.length === 0) return [];

  const ordered = orderModelsForImport(keys, config.modelOrder);
  const skipBundled = new Set<string>();
  const jobs: ImportChunkJob[] = [];

  const pushModelJobs = (primary: string) => {
    if (skipBundled.has(primary)) return;
    const rows = data[primary];
    if (!Array.isArray(rows) || rows.length === 0) return;

    const bundleExtras = (config.bundles[primary] ?? []).filter((extra) => {
      if (skipBundled.has(extra)) return false;
      const extraRows = data[extra];
      return Array.isArray(extraRows) && extraRows.length > 0;
    });
    bundleExtras.forEach((extra) => skipBundled.add(extra));

    const chunkSize =
      config.modelChunkSizes?.[primary] ?? config.rowChunkSize;
    const chunks = chunkArray(rows, chunkSize);
    /** post JSON nặng: pivot tách request riêng để transaction nhỏ hơn + metric rõ hơn. */
    const deferPivotBundle =
      bundleExtras.length > 0 &&
      (chunks.length > 1 || primary === "post");

    chunks.forEach((chunk, chunkIndex) => {
      const payload: Record<string, unknown[]> = { [primary]: chunk };
      const bundledModels: string[] = [];

      if (!deferPivotBundle && chunkIndex === 0) {
        for (const extra of bundleExtras) {
          payload[extra] = data[extra] as unknown[];
          bundledModels.push(extra);
        }
      }

      const recordCount = Object.values(payload).reduce(
        (sum, value) => sum + value.length,
        0,
      );

      jobs.push({
        label:
          chunks.length > 1
            ? `${primary} (lô ${chunkIndex + 1}/${chunks.length})`
            : primary,
        primaryModel: primary,
        // Lô đầu: xóa bảng (skipClear=false). Các lô sau: append (skipClear=true).
        skipClear: chunkIndex !== 0,
        payload,
        recordCount,
        bundledModels,
        isLastChunkForModel: false,
      });
    });

    if (deferPivotBundle) {
      const pivotPrimary = bundleExtras[0]!;
      const pivotPayload: Record<string, unknown[]> = {};
      const pivotBundled: string[] = [];
      for (const extra of bundleExtras) {
        pivotPayload[extra] = data[extra] as unknown[];
        if (extra !== pivotPrimary) pivotBundled.push(extra);
      }
      const pivotCount = Object.values(pivotPayload).reduce(
        (sum, value) => sum + value.length,
        0,
      );
      jobs.push({
        label:
          pivotBundled.length > 0
            ? `${pivotPrimary} + ${pivotBundled.join(", ")}`
            : pivotPrimary,
        primaryModel: pivotPrimary,
        skipClear: false,
        payload: pivotPayload,
        recordCount: pivotCount,
        bundledModels: pivotBundled,
        isLastChunkForModel: false,
      });
    }
  };

  for (const primary of ordered) {
    pushModelJobs(primary);
  }
  for (const key of keys) {
    if (!ordered.includes(key)) {
      pushModelJobs(key);
    }
  }

  const lastJobIndexByModel = new Map<string, number>();
  jobs.forEach((job, index) => {
    lastJobIndexByModel.set(job.primaryModel, index);
  });
  jobs.forEach((job, index) => {
    job.isLastChunkForModel =
      lastJobIndexByModel.get(job.primaryModel) === index;
  });

  return jobs;
}

export function buildInitialImportProgress(
  data: Record<string, unknown[]>,
  config: ImportConfig,
  jobs: ImportChunkJob[],
): Pick<
  ImportProgressState,
  "models" | "total" | "totalRecords"
> {
  const keys = Object.keys(data).filter(
    (key) => Array.isArray(data[key]) && data[key].length > 0,
  );
  const ordered = orderModelsForImport(keys, config.modelOrder);
  const skipBundled = new Set<string>();
  const models: ImportModelProgress[] = [];
  let totalRecords = 0;

  const addModel = (name: string) => {
    const rows = data[name];
    if (!Array.isArray(rows) || rows.length === 0) return;
    models.push({ name, records: rows.length, status: "pending" });
    totalRecords += rows.length;
  };

  for (const primary of ordered) {
    if (skipBundled.has(primary)) continue;
    addModel(primary);
    for (const extra of config.bundles[primary] ?? []) {
      if (skipBundled.has(extra)) continue;
      const extraRows = data[extra];
      if (!Array.isArray(extraRows) || extraRows.length === 0) continue;
      skipBundled.add(extra);
      addModel(extra);
    }
  }
  for (const key of keys) {
    if (!models.some((model) => model.name === key)) {
      addModel(key);
    }
  }

  return {
    models,
    total: jobs.length,
    totalRecords,
  };
}

export async function fetchImportConfig(
  apiBase: string,
  authHeaders: () => HeadersInit,
): Promise<ImportConfig> {
  const res = await fetch(`${apiBase}/admin/system/import-config`, {
    headers: authHeaders(),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(
      text.length > 200 ? `${text.slice(0, 200)}…` : text || `HTTP ${res.status}`,
    );
  }
  const json = (await res.json()) as ApiEnvelope<ImportConfig>;
  if (!json.success || !json.data) {
    throw new Error(json.message || "API không trả cấu hình import hợp lệ.");
  }
  return json.data;
}

export type RunChunkedImportOptions = {
  apiBase: string;
  authHeaders: () => HeadersInit;
  config: ImportConfig;
  data: Record<string, unknown[]>;
  onProgress: (state: ImportProgressState) => void;
  toastFetchError: (res: Response) => Promise<string>;
};

async function runImportJobsInPool<T>(
  items: T[],
  concurrency: number,
  worker: (item: T, index: number) => Promise<void>,
): Promise<void> {
  if (items.length === 0) return;
  const limit = Math.max(1, Math.min(concurrency, items.length));
  let cursor = 0;
  async function runWorker(): Promise<void> {
    while (true) {
      const index = cursor;
      cursor += 1;
      if (index >= items.length) return;
      await worker(items[index]!, index);
    }
  }
  await Promise.all(Array.from({ length: limit }, () => runWorker()));
}

export async function runChunkedImport({
  apiBase,
  authHeaders,
  config,
  data,
  onProgress,
  toastFetchError,
}: RunChunkedImportOptions): Promise<{ success: boolean; message: string }> {
  const jobs = buildChunkedImportJobs(data, config);
  if (jobs.length === 0) {
    return { success: false, message: "Không có dữ liệu để import." };
  }

  const initial = buildInitialImportProgress(data, config, jobs);
  let cumulativeImported = 0;
  let modelStates: ImportModelProgress[] = initial.models.map((model) => ({
    ...model,
  }));
  const timingByName = new Map<string, ImportModelTimingStats>();
  const jobTimings: ImportJobTimingEntry[] = [];
  const importWallStarted = nowMs();

  const emitProgress = (
    patch: Partial<ImportProgressState> & { models?: ImportModelProgress[] },
  ) => {
    if (patch.models) {
      modelStates = attachTimingsToModels(patch.models, timingByName);
    } else {
      modelStates = attachTimingsToModels(modelStates, timingByName);
    }
    onProgress({
      active: true,
      models: modelStates,
      currentIndex: patch.currentIndex ?? 0,
      total: initial.total,
      totalRecords: initial.totalRecords,
      cumulativeImported: patch.cumulativeImported ?? cumulativeImported,
      status: patch.status ?? "importing",
      message: patch.message,
      totalDurationMs: patch.totalDurationMs,
      jobTimings: patch.jobTimings ?? jobTimings,
    });
  };

  const parallelConcurrency = Math.max(
    1,
    config.parallelChunkConcurrency ?? 3,
  );

  emitProgress({
    currentIndex: 0,
    cumulativeImported: 0,
    status: "importing",
    message: `Import theo ${jobs.length} lô${parallelConcurrency > 1 ? ` (song song tối đa ${parallelConcurrency})` : ""}…`,
  });

  const executeImportJob = async (
    job: ImportChunkJob,
    jobIndex: number,
  ): Promise<{ success: boolean; message?: string }> => {
    const chunkDetail = job.label.includes("lô")
      ? job.label.replace(`${job.primaryModel} `, "")
      : undefined;
    const jobStarted = nowMs();
    const primaryRecords =
      modelStates.find((m) => m.name === job.primaryModel)?.records ?? 0;

    markModelImportStart(
      timingByName,
      job.primaryModel,
      primaryRecords,
      jobStarted,
    );
    for (const bundled of job.bundledModels) {
      const bundledRecords =
        modelStates.find((m) => m.name === bundled)?.records ?? 0;
      markModelImportStart(timingByName, bundled, bundledRecords, jobStarted);
    }

    emitProgress({
      models: modelStates.map((model) => {
        if (model.name === job.primaryModel) {
          return {
            ...model,
            status: "importing" as const,
            detail: chunkDetail,
          };
        }
        if (
          job.bundledModels.includes(model.name) &&
          model.status === "pending"
        ) {
          return { ...model, status: "importing" as const };
        }
        return model;
      }),
      currentIndex: jobIndex,
      cumulativeImported,
      status: "importing",
      message: `Đang gửi ${job.label}…`,
    });

    const query = new URLSearchParams({
      model: job.primaryModel,
      skipClear: String(job.skipClear),
      stream: "false",
    });
    const res = await fetch(`${apiBase}/admin/system/import?${query}`, {
      method: "POST",
      headers: {
        ...authHeaders(),
        "Content-Type": "application/json",
      },
      body: JSON.stringify(job.payload),
    });

    if (!res.ok) {
      const errMsg = formatImportErrorMessage(await toastFetchError(res));
      emitProgress({
        models: modelStates.map((model) =>
          model.name === job.primaryModel ||
          (job.bundledModels.includes(model.name) &&
            (model.status === "pending" || model.status === "importing"))
            ? {
                ...model,
                status: "error" as const,
                error: errMsg,
              }
            : model.status === "importing"
              ? { ...model, status: "skipped" as const }
              : model,
        ),
        currentIndex: jobIndex,
        cumulativeImported,
        status: "error",
        message: errMsg,
      });
      return { success: false, message: errMsg };
    }

    const envelope = (await res.json()) as ApiEnvelope<ImportResultPayload>;
    const result = envelope.data ?? (envelope as ImportResultPayload);
    const httpMs = nowMs() - jobStarted;
    const jobModelNames = [job.primaryModel, ...job.bundledModels];
    addHttpJobDuration(timingByName, modelStates, jobModelNames, httpMs);
    applyServerTimings(timingByName, modelStates, result.timing?.models);
    jobTimings.push({
      label: job.label,
      primaryModel: job.primaryModel,
      bundledModels: job.bundledModels,
      recordCount: job.recordCount,
      httpMs,
      serverRequestMs: result.timing?.requestMs,
    });

    const rowErrors = result.rowErrors ?? [];
    const importOk =
      envelope.success !== false &&
      result.success !== false &&
      rowErrors.length === 0;
    const errMsg = buildImportJobFailureMessage({
      jobLabel: job.label,
      primaryModel: job.primaryModel,
      rowErrors,
      fallbackMessage: result.message?.trim(),
    });

    if (!importOk) {
      emitProgress({
        models: modelStates.map((model) => {
          const modelRowErrors = rowErrors.filter(
            (row) => row.model === model.name,
          );
          if (modelRowErrors.length > 0) {
            return applyRowErrorsToModel(model, model.name, rowErrors);
          }
          if (model.name === job.primaryModel) {
            return {
              ...model,
              status: "error" as const,
              error: errMsg,
            };
          }
          if (
            job.bundledModels.includes(model.name) &&
            (model.status === "pending" || model.status === "importing")
          ) {
            return {
              ...model,
              status: "error" as const,
              error: errMsg,
            };
          }
          if (model.status === "pending" || model.status === "importing") {
            return { ...model, status: "skipped" as const };
          }
          return model;
        }),
        currentIndex: jobIndex,
        cumulativeImported,
        status: "error",
        message: errMsg,
      });
      return {
        success: false,
        message: errMsg,
      };
    }

    cumulativeImported += job.recordCount;
    const jobEnded = nowMs();

    if (job.isLastChunkForModel) {
      markModelImportEnd(
        timingByName,
        job.primaryModel,
        primaryRecords,
        jobEnded,
      );
    }
    for (const bundled of job.bundledModels) {
      const bundledRecords =
        modelStates.find((m) => m.name === bundled)?.records ?? 0;
      markModelImportEnd(timingByName, bundled, bundledRecords, jobEnded);
    }

    emitProgress({
      models: modelStates.map((model) => {
        if (model.name === job.primaryModel) {
          if (job.isLastChunkForModel) {
            return { ...model, status: "done" as const, detail: undefined };
          }
          return {
            ...model,
            status: "importing" as const,
            detail: chunkDetail,
          };
        }
        if (job.bundledModels.includes(model.name)) {
          return { ...model, status: "done" as const };
        }
        return model;
      }),
      currentIndex: jobIndex,
      cumulativeImported,
      status: "importing",
    });

    return { success: true };
  };

  let jobCursor = 0;
  let importFailed: { success: false; message: string } | null = null;

  while (jobCursor < jobs.length && !importFailed) {
    const job = jobs[jobCursor]!;

    if (!job.skipClear) {
      const result = await executeImportJob(job, jobCursor);
      if (!result.success) {
        importFailed = {
          success: false,
          message: result.message ?? "Import thất bại",
        };
        break;
      }
      jobCursor += 1;
      continue;
    }

    const parallelBatch: Array<{ job: ImportChunkJob; index: number }> = [];
    const primary = job.primaryModel;
    while (
      jobCursor < jobs.length &&
      jobs[jobCursor]!.skipClear &&
      jobs[jobCursor]!.primaryModel === primary
    ) {
      parallelBatch.push({ job: jobs[jobCursor]!, index: jobCursor });
      jobCursor += 1;
    }

    const batchConcurrency = Math.max(
      1,
      config.modelParallelConcurrency?.[primary] ?? parallelConcurrency,
    );

    await runImportJobsInPool(
      parallelBatch,
      batchConcurrency,
      async ({ job: parallelJob, index }) => {
        if (importFailed) return;
        const result = await executeImportJob(parallelJob, index);
        if (!result.success) {
          importFailed = {
            success: false,
            message: result.message ?? "Import thất bại",
          };
        }
      },
    );
  }

  if (importFailed) {
    return importFailed;
  }

  const totalDurationMs = Math.round(nowMs() - importWallStarted);
  const slowest = [...timingByName.entries()]
    .filter(([, t]) => t.wallMs > 0)
    .sort((a, b) => b[1].wallMs - a[1].wallMs)[0];
  const doneMessage = slowest
    ? `Import hoàn tất — ${cumulativeImported.toLocaleString("vi-VN")} bản ghi qua ${jobs.length} lô · chậm nhất: ${slowest[0]} (${formatImportDuration(slowest[1].wallMs)}).`
    : `Import hoàn tất — ${cumulativeImported.toLocaleString("vi-VN")} bản ghi qua ${jobs.length} lô.`;
  emitProgress({
    models: modelStates.map((model) =>
      model.status === "pending" || model.status === "importing"
        ? { ...model, status: "done" as const }
        : model,
    ),
    currentIndex: jobs.length - 1,
    cumulativeImported,
    status: "done",
    message: doneMessage,
    totalDurationMs,
  });

  return { success: true, message: doneMessage };
}

src/app/data/_component/import-error-mes.content:
import {
  formatImportDuration,
  formatImportThroughput,
  formatModelTimingSummary,
  type ImportJobTimingEntry,
  type ImportModelTimingStats,
} from "./import-timing";

const MAX_IMPORT_ERROR_LENGTH = 220;

export type ImportRowError = {
  model: string;
  index: number;
  message: string;
};

/** Thông báo tổng hợp từ API — không mang chi tiết từng dòng. */
export function isGenericImportSummaryMessage(message: string): boolean {
  const trimmed = message.trim();
  return (
    /^imported with \d+ row error/i.test(trimmed) ||
    /^data imported successfully$/i.test(trimmed)
  );
}

/** Rút gọn lỗi SQL/DB dài thành dòng dễ đọc cho UI. */
export function formatImportErrorMessage(
  raw: string,
  maxLength = MAX_IMPORT_ERROR_LENGTH,
): string {
  const trimmed = raw.trim();
  if (!trimmed) return trimmed;

  const classified = classifyImportErrorDetail(trimmed);
  if (classified !== trimmed) {
    return truncateText(classified, maxLength);
  }

  const dashTail = trimmed.match(/ - ([\s\S]+)$/);
  if (dashTail?.[1]) {
    const summary = classifyImportErrorDetail(dashTail[1].trim());
    if (summary.length > 0 && summary.length < trimmed.length) {
      return truncateText(summary, maxLength);
    }
  }

  if (/^insert into\s+/i.test(trimmed)) {
    return "Lỗi khi ghi dữ liệu vào database.";
  }

  if (/^update\s+/i.test(trimmed) || /^delete from\s+/i.test(trimmed)) {
    return "Lỗi khi cập nhật dữ liệu trong database.";
  }

  return truncateText(trimmed, maxLength);
}

/** Diễn giải lỗi DB thành tiếng Việt ngắn gọn. */
export function classifyImportErrorDetail(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return trimmed;

  const duplicateMatch = trimmed.match(
    /duplicate entry '([^']*)' for key '([^']+)'/i,
  );
  if (duplicateMatch) {
    const [, value, key] = duplicateMatch;
    const keyLabel =
      key.toLowerCase() === "primary"
        ? "khóa chính (id)"
        : key.toLowerCase() === "unique" || key.includes("unique")
          ? "giá trị duy nhất"
          : `khóa «${key}»`;
    return value
      ? `Trùng ${keyLabel}: «${value}» đã tồn tại`
      : `Trùng ${keyLabel} — bản ghi đã tồn tại trong database`;
  }

  const lower = trimmed.toLowerCase();
  if (lower.includes("foreign key constraint") || lower.includes("cannot add or update")) {
    return "Vi phạm khóa ngoại — bảng liên quan chưa có dữ liệu hoặc id không khớp";
  }
  if (lower.includes("cannot delete or update a parent row")) {
    return "Không thể ghi đè — còn bản ghi con tham chiếu tới dòng này";
  }
  if (lower.includes("data too long")) {
    return "Dữ liệu quá dài so với cột trong database";
  }
  if (lower.includes("incorrect datetime") || lower.includes("invalid datetime")) {
    return "Định dạng ngày giờ không hợp lệ";
  }
  if (lower.includes("cannot be null") || lower.includes("column cannot be null")) {
    return "Thiếu trường bắt buộc (NOT NULL)";
  }

  return trimmed;
}

export function formatRowErrorLine(error: ImportRowError): string {
  return `Dòng ${error.index + 1}: ${classifyImportErrorDetail(error.message)}`;
}

export function getModelRowErrorDetails(
  modelName: string,
  rowErrors: ImportRowError[],
  maxLines = 6,
): string[] {
  return rowErrors
    .filter((row) => row.model === modelName)
    .slice(0, maxLines)
    .map((row) => formatRowErrorLine(row));
}

export function buildModelImportErrorSummary(
  modelName: string,
  rowErrors: ImportRowError[],
): {
  summary: string;
  details: string[];
  fullTitle?: string;
} {
  const modelErrors = rowErrors.filter((row) => row.model === modelName);
  if (modelErrors.length === 0) {
    return { summary: "", details: [] };
  }

  const firstDetail = classifyImportErrorDetail(modelErrors[0]!.message);
  const errorKind = (msg: string) => {
    const lower = classifyImportErrorDetail(msg).toLowerCase();
    if (lower.startsWith("trùng khóa chính")) return "duplicate-pk";
    if (lower.startsWith("trùng")) return "duplicate";
    if (lower.includes("khóa ngoại")) return "fk";
    return classifyImportErrorDetail(msg);
  };
  const firstKind = errorKind(modelErrors[0]!.message);
  const allSame = modelErrors.every(
    (row) => errorKind(row.message) === firstKind,
  );

  const details = allSame
    ? modelErrors.length === 1
      ? [formatRowErrorLine(modelErrors[0]!)]
      : [
          formatRowErrorLine(modelErrors[0]!),
          `… cùng lỗi trên ${modelErrors.length} dòng trong file`,
        ]
    : (() => {
        const lines = getModelRowErrorDetails(modelName, rowErrors);
        const remaining = modelErrors.length - lines.length;
        if (remaining > 0) {
          lines.push(`… và ${remaining} lỗi khác`);
        }
        return lines;
      })();

  const summary = allSame
    ? firstKind === "duplicate-pk"
      ? `${modelErrors.length} bản ghi lỗi — trùng khóa chính (id đã tồn tại trong database)`
      : `${modelErrors.length} bản ghi lỗi — ${firstDetail}`
    : `${modelErrors.length} bản ghi lỗi`;

  const fullTitle = modelErrors
    .map((row) => `[${row.model}#${row.index + 1}] ${row.message}`)
    .join("\n");

  return { summary, details, fullTitle };
}

export type ImportProgressReportInput = {
  status: string;
  message?: string;
  cumulativeImported: number;
  totalRecords: number;
  currentIndex: number;
  total: number;
  totalDurationMs?: number;
  jobTimings?: ImportJobTimingEntry[];
  models: Array<{
    name: string;
    records: number;
    status: string;
    detail?: string;
    error?: string;
    rowErrorDetails?: string[];
    errorTitle?: string;
    timing?: ImportModelTimingStats;
  }>;
};

const IMPORT_PROGRESS_STATUS_LABEL: Record<string, string> = {
  idle: "Chờ",
  importing: "Đang import",
  done: "Hoàn tất",
  error: "Có lỗi",
};

const IMPORT_MODEL_STATUS_LABEL: Record<string, string> = {
  pending: "Chờ",
  importing: "Đang import",
  done: "Xong",
  error: "Lỗi",
  skipped: "Bỏ qua",
};

function formatModelStatusLine(model: ImportProgressReportInput["models"][number]): string {
  const statusLabel =
    IMPORT_MODEL_STATUS_LABEL[model.status] ?? model.status;
  const parts = [
    `- ${model.name} (${model.records.toLocaleString("vi-VN")} bản ghi): ${statusLabel}`,
  ];
  if (model.timing && model.timing.wallMs > 0) {
    parts.push(`  Thời gian: ${formatModelTimingSummary(model.timing)}`);
  }
  if (model.detail) parts.push(`  Lô: ${model.detail}`);
  if (model.error) parts.push(`  Lỗi: ${model.error}`);
  for (const detail of model.rowErrorDetails ?? []) {
    parts.push(`    ${detail}`);
  }
  return parts.join("\n");
}

/** Văn bản đầy đủ để copy báo cáo import (tiến độ + lỗi + SQL gốc nếu có). */
export function buildImportProgressReport(
  progress: ImportProgressReportInput,
): string {
  const statusLabel =
    IMPORT_PROGRESS_STATUS_LABEL[progress.status] ?? progress.status;
  const lines: string[] = [
    "=== Báo cáo import ===",
    `Trạng thái: ${statusLabel}`,
    `Tiến độ: ${progress.cumulativeImported.toLocaleString("vi-VN")} / ${progress.totalRecords.toLocaleString("vi-VN")} bản ghi`,
  ];

  if (progress.total > 0) {
    lines.push(
      `Lô HTTP: ${Math.min(progress.currentIndex + 1, progress.total)} / ${progress.total}`,
    );
  }
  if (progress.message?.trim()) {
    lines.push(`Hoạt động: ${progress.message.trim()}`);
  }

  if (progress.totalDurationMs != null && progress.totalDurationMs > 0) {
    const throughput = formatImportThroughput(
      progress.cumulativeImported,
      progress.totalDurationMs,
    );
    lines.push(
      `Tổng thời gian: ${formatImportDuration(progress.totalDurationMs)}${throughput !== "—" ? ` (${throughput})` : ""}`,
    );
  }

  if (progress.models.length > 0) {
    lines.push("", "=== Trạng thái từng bảng ===");
    for (const model of progress.models) {
      lines.push(formatModelStatusLine(model));
    }

    const timedModels = progress.models
      .filter((m) => m.timing && m.timing.wallMs > 0)
      .sort((a, b) => (b.timing?.wallMs ?? 0) - (a.timing?.wallMs ?? 0));
    if (timedModels.length > 0) {
      lines.push("", "=== Thời gian từng bảng (chậm → nhanh) ===");
      for (const model of timedModels) {
        lines.push(
          `- ${model.name}: ${formatModelTimingSummary(model.timing!)}`,
        );
      }
    }
  }

  if (progress.jobTimings && progress.jobTimings.length > 0) {
    lines.push("", "=== Chi tiết từng lô HTTP ===");
    for (const job of progress.jobTimings) {
      const bundled =
        job.bundledModels.length > 0
          ? ` + ${job.bundledModels.join(", ")}`
          : "";
      const server =
        job.serverRequestMs != null
          ? ` · server ${formatImportDuration(job.serverRequestMs)}`
          : "";
      lines.push(
        `- ${job.label}: ${job.recordCount.toLocaleString("vi-VN")} bản ghi · HTTP ${formatImportDuration(job.httpMs)}${server}${bundled}`,
      );
    }
  }

  const errorModels = progress.models.filter((m) => m.status === "error");
  const skippedModels = progress.models.filter((m) => m.status === "skipped");

  if (errorModels.length > 0) {
    lines.push("", "=== Chi tiết lỗi (SQL gốc) ===");
    for (const model of errorModels) {
      if (model.errorTitle?.trim()) {
        lines.push("");
        lines.push(`[${model.name}]`);
        lines.push(model.errorTitle.trim());
      }
    }
  }

  if (skippedModels.length > 0) {
    lines.push("", "=== Bảng bỏ qua ===");
    for (const model of skippedModels) {
      lines.push(`- ${model.name} (${model.records.toLocaleString("vi-VN")} bản ghi)`);
    }
  }

  return lines.join("\n");
}

export function buildModelImportCopyText(model: {
  name: string;
  records: number;
  detail?: string;
  error?: string;
  rowErrorDetails?: string[];
  errorTitle?: string;
}): string {
  const lines = [
    `[${model.name}] ${model.records.toLocaleString("vi-VN")} bản ghi`,
  ];
  if (model.detail) lines.push(`Lô: ${model.detail}`);
  if (model.error) lines.push(model.error);
  for (const detail of model.rowErrorDetails ?? []) {
    lines.push(detail);
  }
  if (model.errorTitle?.trim()) {
    lines.push("", "--- Lỗi gốc (API) ---", model.errorTitle.trim());
  }
  return lines.join("\n");
}

export function buildImportJobFailureMessage(options: {
  jobLabel: string;
  primaryModel: string;
  rowErrors?: ImportRowError[];
  fallbackMessage?: string;
}): string {
  const { jobLabel, primaryModel, rowErrors, fallbackMessage } = options;

  if (rowErrors?.length) {
    const { summary } = buildModelImportErrorSummary(primaryModel, rowErrors);
    if (summary) {
      return `${jobLabel}: ${summary}`;
    }
    const first = formatRowErrorLine(rowErrors[0]!);
    const extra =
      rowErrors.length > 1 ? ` (+${rowErrors.length - 1} lỗi khác)` : "";
    return `${jobLabel}: ${first}${extra}`;
  }

  if (fallbackMessage && !isGenericImportSummaryMessage(fallbackMessage)) {
    return formatImportErrorMessage(fallbackMessage);
  }

  return `Import ${jobLabel} thất bại`;
}

function truncateText(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}…`;
}

