                )}
              />
              <Controller
                name="code"
                control={control}
                render={({ field, fieldState }) => (
                  <FormFieldCol label="Mã ngành" required>
                    <Input
                      placeholder="VD: CNTT"
                      {...field}
                      className={cn(fieldState.error && "border-destructive")}
                    />
                    {fieldState.error && (
                      <FieldError>{fieldState.error.message}</FieldError>
                    )}
                  </FormFieldCol>
                )}
              />
