"use client"

import type { ColumnDef, FilterFnOption } from "@tanstack/react-table"
import {
  UsageStatusBadge,
  type UsageStatusTone,
} from "@ui/components/usage-status-badge"
import {
  BarChart3,
  CheckCircle2,
  Clock,
  GraduationCap,
  Settings2,
  Trash2,
  XCircle,
} from "lucide-react"
import {
  DataTableRowActionsMenu,
  defineDataTableActionsColumn,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import type { MyStudentRow } from "./types"
import { defineRelationExportColumns } from "@ui/components/data-table"
import {
  adminDateRangeFilterFn,
  defineAdminCreatedAtColumn,
} from "@/lib/admin-table-columns"
import { formatAdminDateTime } from "@/lib/format-admin-datetime"

function recordLabel(row: MyStudentRow): string {
  return row.studentName?.trim() || row.studentCode
}

export interface MyStudentsColumnsProps {
  onViewGrades: (row: MyStudentRow) => void
  onDelete: (row: MyStudentRow) => void | Promise<void>
  canDelete: boolean
  deleteBusy?: boolean
}

export function getMyStudentsColumns(
  props: MyStudentsColumnsProps
): ColumnDef<MyStudentRow>[] {
  const { onViewGrades, onDelete, canDelete, deleteBusy } = props

  return [
    {
      id: "student",
      header: "Sinh viên",
      accessorFn: (row) =>
        [row.studentCode, row.studentName].filter(Boolean).join(" "),
      enableColumnFilter: true,
      meta: {
        filterLabel: "Sinh viên",
        filterPlaceholder: "Mã hoặc họ tên…",
      },
      enableSorting: true,
      sortingFn: (a, b) => {
        const la = recordLabel(a.original)
        const lb = recordLabel(b.original)
        return la.localeCompare(lb, "vi")
      },
      cell: ({ row }) => (
        <div className="flex items-center gap-2.5">
          <div className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400">
            <GraduationCap className="size-4" aria-hidden />
          </div>
          <div className="min-w-0">
            {row.original.studentName && (
              <p className="truncate font-medium">{row.original.studentName}</p>
            )}
            <p className="font-mono text-xs text-muted-foreground">
              {row.original.studentCode}
            </p>
          </div>
        </div>
      ),
    },
    {
      accessorKey: "note",
      header: "Ghi chú",
      enableColumnFilter: true,
      cell: ({ getValue }) => {
        const v = getValue() as string | null
        return v ? (
          <span className="text-xs text-muted-foreground">{v}</span>
        ) : (
          <span className="text-xs italic opacity-40">—</span>
        )
      },
    },
    defineAdminCreatedAtColumn<MyStudentRow>({ header: "Ngày gửi" }),
    {
      accessorKey: "status",
      header: "Trạng thái",
      enableColumnFilter: true,
      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        return String(row.getValue(columnId)) === String(filterValue)
      },
      enableSorting: false,
      meta: {
        filterVariant: "select",
        selectOptions: [
          { value: "pending", label: "Chờ duyệt" },
          { value: "approved", label: "Đã duyệt" },
          { value: "rejected", label: "Từ chối" },
        ],
      },
      cell: ({ getValue }) => {
        const s = getValue() as MyStudentRow["status"]
        const STATUS_CONFIG: Record<
          MyStudentRow["status"],
          { label: string; icon: typeof Clock; tone: UsageStatusTone }
        > = {
          pending: { label: "Chờ duyệt", icon: Clock, tone: "warning" },
          approved: { label: "Đã duyệt", icon: CheckCircle2, tone: "success" },
          rejected: { label: "Từ chối", icon: XCircle, tone: "danger" },
        }
        const cfg = STATUS_CONFIG[s]
        const StatusIcon = cfg.icon
        return (
          <UsageStatusBadge tone={cfg.tone} className="gap-1 text-[10px]">
            <StatusIcon className="size-3 shrink-0" aria-hidden />
            {cfg.label}
          </UsageStatusBadge>
        )
      },
    },
    {
      accessorKey: "reviewedAt",
      header: "Duyệt lúc",
      enableColumnFilter: true,
      filterFn: adminDateRangeFilterFn as FilterFnOption<MyStudentRow>,
      meta: {
        defaultHidden: true,
        filterVariant: "date-range",
        filterPlaceholder: "Chọn khoảng ngày",
      },
      cell: ({ getValue }) => {
        const v = getValue() as string | null
        return (
          <span className="text-xs text-muted-foreground tabular-nums">
            {formatAdminDateTime(v)}
          </span>
        )
      },
    },
    ...defineRelationExportColumns<MyStudentRow>(
      [{ id: "parentId", header: "ID phụ huynh", getValue: (r) => r.parentId }],
      { enableColumnFilter: false }
    ),
    defineDataTableActionsColumn<MyStudentRow>({
      cell: ({ row }) => {
        const data = row.original
        const label = recordLabel(data)
        const actions: DataTableRowActionItem[] = []

        if (data.status === "approved") {
          actions.push({
            key: "grades",
            label: "Xem kết quả học tập",
            hint: "Bảng điểm chi tiết, TB năm học và học kỳ",
            onClick: () => onViewGrades(data),
            icon: <BarChart3 />,
            group: "primary",
          })
        }

        if (canDelete) {
          const approved = data.status === "approved"
          actions.push({
            key: "unlink",
            label: approved ? "Gỡ liên kết" : "Xóa yêu cầu",
            hint: approved
              ? "Ngừng theo dõi bảng điểm sinh viên này"
              : "Xóa yêu cầu liên kết chưa hoặc đã bị từ chối",
            onClick: () => onDelete(data),
            icon: <Trash2 />,
            group: "danger",
            menuVariant: "destructive",
            confirm: approved
              ? {
                  title: `Gỡ liên kết ${label}?`,
                  description:
                    "Bạn sẽ không còn xem được bảng điểm của sinh viên này.",
                  confirmLabel: "Gỡ liên kết",
                  destructive: true,
                }
              : {
                  title: `Xóa yêu cầu ${label}?`,
                  description: "Thao tác không thể hoàn tác.",
                  confirmLabel: "Xóa",
                  destructive: true,
                },
          })
        }

        return (
          <DataTableRowActionsMenu
            actions={actions}
            busy={deleteBusy}
            groups={{
              primary: { label: "Theo dõi", icon: Settings2 },
              danger: { label: "Liên kết", sublabel: true },
            }}
          />
        )
      },
    }),
  ]
}

export function getMyStudentGlobalFilterText(row: MyStudentRow): string {
  return [row.studentCode, row.studentName, row.note].filter(Boolean).join(" ")
}

src/app/my-students/_component/detailed-.content:
"use client"

import { useMemo, useState } from "react"
import { type ColumnDef } from "@tanstack/react-table"
import { Loader2, ChevronDown, ChevronRight } from "lucide-react"
import { Badge } from "@ui/components/badge"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@ui/components/collapsible"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@ui/components/select"
import { cn } from "@ui/lib/utils"
import { MyStudentsScoreTable } from "./_table/my-students-score-table"
import type { DetailedScore } from "@/types/student-scores"
import { formatScore, formatGrade } from "./score-utils"
import { ScrollArea } from "@ui/components/scroll-area"

interface Props {
  scores?: DetailedScore[]
  isLoading: boolean
}

function SubjectTable({ subjects }: { subjects: DetailedScore[] }) {
  const columns = useMemo<ColumnDef<DetailedScore>[]>(
    () => [
      {
        id: "subject",
        header: "Môn học",
        accessorKey: "curriculumName",
        meta: {
          exportValue: (row: DetailedScore) =>
            `${row.curriculumName ?? ""} (${row.curriculumID ?? ""})`.trim(),
        },
        cell: ({ row }) => (
          <div>
            <div className="text-sm font-medium">{row.original.curriculumName}</div>
            <div className="text-xs text-muted-foreground">{row.original.curriculumID}</div>
          </div>
        ),
      },
      {
        id: "mark10",
        header: () => <div className="w-full text-center">Hệ 10</div>,
        accessorKey: "mark10",
        cell: ({ row }) => {
          const f = formatScore(row.original.mark10, "10")
          return <div className={cn("w-full text-center tabular-nums", f.color)}>{f.text}</div>
        },
      },
      {
        id: "mark4",
        header: () => <div className="w-full text-center">Hệ 4</div>,
        accessorKey: "mark4",
        cell: ({ row }) => {
          const f = formatScore(row.original.mark4, "4")
          return <div className={cn("w-full text-center tabular-nums", f.color)}>{f.text}</div>
        },
      },
      {
        id: "markLetter",
        header: () => <div className="w-full text-center">Điểm chữ</div>,
        accessorKey: "markLetter",
        cell: ({ row }) => {
          const g = formatGrade(row.original.markLetter)
          return (
            <div className="flex justify-center">
              <Badge variant="outline" className={cn("px-1.5 py-0", g.color)}>{g.text}</Badge>
            </div>
          )
        },
      },
    ],
    []
  )

  if (!subjects.length)
    return (
      <p className="py-3 text-sm text-muted-foreground">Không có dữ liệu</p>
    )
  return (
    <MyStudentsScoreTable
      data={subjects}
      columns={columns}
      emptyLabel="Không có dữ liệu"
    />
  )
}

export const DetailedScoresList = ({ scores, isLoading }: Props) => {
  const [filterYear, setFilterYear] = useState("all")
  const [openTerms, setOpenTerms] = useState<Set<string>>(new Set())

  const years = useMemo(
    () =>
      scores
        ? [...new Set(scores.map((s) => s.yearStudy).filter(Boolean))]
            .sort()
            .reverse()
        : [],
    [scores]
  )

  const grouped = useMemo(() => {
    if (!scores) return {}
    const filtered =
      filterYear === "all"
        ? scores
        : scores.filter((s) => s.yearStudy === filterYear)
    const map: Record<string, Record<string, DetailedScore[]>> = {}
    filtered.forEach((s) => {
      const y = s.yearStudy || "Khác"
      const t = s.termID || "Khác"
      ;(map[y] ??= {})[t] ??= []
      map[y][t].push(s)
    })
    return map
  }, [scores, filterYear])

  if (isLoading) {
    return (
      <div className="flex justify-center py-8">
        <Loader2 className="size-5 animate-spin text-muted-foreground" />
      </div>
    )
  }
  if (!scores?.length) {
    return (
      <div className="py-8 text-center text-sm text-muted-foreground">
        Chưa có dữ liệu điểm chi tiết
      </div>
    )
  }

  return (
    <ScrollArea className="max-h-[50vh] space-y-3 overflow-y-auto">
      <div className="space-y-3">
        <Select
          value={filterYear}
          onValueChange={(v) => setFilterYear(v ?? "all")}
        >
          <SelectTrigger className="w-44">
            <SelectValue>
              {filterYear === "all" ? "Tất cả năm học" : filterYear}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Tất cả năm học</SelectItem>
            {years.map((y) => (
              <SelectItem key={y} value={y}>
                {y}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {Object.keys(grouped).length === 0 ? (
          <div className="py-6 text-center text-sm text-muted-foreground">
            Không tìm thấy dữ liệu
          </div>
        ) : (
          Object.entries(grouped)
            .sort(([a], [b]) => b.localeCompare(a))
            .map(([year, terms]) => (
              <div key={year}>
                <div className="mb-1 text-sm font-semibold text-foreground">
                  Năm học {year}
                </div>
                {Object.entries(terms)
                  .sort(([a], [b]) => a.localeCompare(b))
                  .map(([term, subjects]) => {
                    const key = `${year}-${term}`
                    const toggleTerm = () =>
                      setOpenTerms((prev) => {
                        const next = new Set(prev)
                        if (next.has(key)) {
                          next.delete(key)
                        } else {
                          next.add(key)
                        }
                        return next
                      })
                    return (
                      <Collapsible
                        key={key}
                        open={openTerms.has(key)}
                        onOpenChange={toggleTerm}
                        className="mb-2"
                      >
                        <CollapsibleTrigger
                          className={cn(
                            "flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-sm",
                            openTerms.has(key)
                              ? "rounded-t-md bg-primary text-primary-foreground"
                              : "hover:bg-muted/80"
                          )}
                        >
                          {openTerms.has(key) ? (
                            <ChevronDown className="size-3.5 shrink-0" />
                          ) : (
                            <ChevronRight className="size-3.5 shrink-0" />
                          )}
                          <span>Học kỳ {term}</span>
                          <Badge
                            variant="secondary"
                            className="ml-auto text-xs"
                          >
                            {subjects.length} môn
                          </Badge>
                        </CollapsibleTrigger>
                        <CollapsibleContent className="px-1 pt-2">
                          <SubjectTable subjects={subjects} />
                        </CollapsibleContent>
                      </Collapsible>
                    )
                  })}
              </div>
            ))
        )}
      </div>
    </ScrollArea>
  )
}

