import type { SerializedEditorState, SerializedLexicalNode } from "lexical";
import {
  buildAdminFilterQuery,
  COMMON_FILTER_MAPPINGS,
  normalizeAdminFilterValues,
} from "@/lib";
import { uploadAdminImage } from "@/lib/admin-upload";
import type {
  EditorParagraphNodeShape,
  EditorStateShape,
} from "./types";

export function uploadPostImage(file: File): Promise<string> {
  return uploadAdminImage(file, {
    folderPath: "posts",
    isExistingFolder: true,
  });
}

export {
  slugify,
  formatDateTime,
  buildCategoryOptionTree,
  unwrapApiEnvelope as unwrapEnvelope,
  normalizePagedResult as normalizePaged,
  type CategoryTreeNode,
} from "@workspace/api-client";

export function createParagraphNode(text = ""): EditorParagraphNodeShape {
  return {
    children: text
      ? [
          {
            detail: 0,
            format: 0,
            mode: "normal",
            style: "",
            text,
            type: "text",
            version: 1,
          },
        ]
      : [],
    direction: null,
    format: "",
    indent: 0,
    textFormat: 0,
    textStyle: "",
    type: "paragraph",
    version: 1,
  };
}

export function createSerializedEditorState(
  paragraphs: EditorParagraphNodeShape[]
): SerializedEditorState {
  const state: EditorStateShape = {
    root: {
      children: paragraphs,
      direction: null,
      format: "",
      indent: 0,
      type: "root",
      version: 1,
    },
  };
  return state as SerializedEditorState;
}

export function getSeoStatus(
  length: number,
  recommendedMin: number,
  recommendedMax: number
) {
  if (length === 0) {
    return {
      label: "Chưa có nội dung",
      tone: "destructive" as const,
      hint: `Nên nhập khoảng ${recommendedMin}-${recommendedMax} ký tự.`,
    };
  }
  if (length < recommendedMin) {
    return {
      label: "Hơi ngắn",
      tone: "secondary" as const,
      hint: `Nên tăng lên khoảng ${recommendedMin}-${recommendedMax} ký tự.`,
    };
  }
  if (length > recommendedMax) {
    return {
      label: "Hơi dài",
      tone: "secondary" as const,
      hint: `Nên rút xuống khoảng ${recommendedMin}-${recommendedMax} ký tự.`,
    };
  }
  return {
    label: "Tốt cho SEO",
    tone: "default" as const,
    hint: `Độ dài đang nằm trong khoảng gợi ý ${recommendedMin}-${recommendedMax} ký tự.`,
  };
}

export function buildPostsFilterQuery(
  filters: { id: string; value: unknown }[],
): Record<string, string> {
  const query = buildAdminFilterQuery(filters, COMMON_FILTER_MAPPINGS.posts);
  for (const filter of filters) {
    if (filter.id === "published") {
      const values = normalizeAdminFilterValues(filter.value);
      if (values.length) query.published = values.join(",");
    } else if (filter.id === "categoryId") {
      const values = normalizeAdminFilterValues(filter.value);
      if (values.length) query.categoryId = values.join(",");
    } else if (filter.id === "tagId") {
      const values = normalizeAdminFilterValues(filter.value);
      if (values.length) query.tagId = values.join(",");
    }
  }
  return query;
}

export function isSerializedEditorState(
  value: unknown
): value is SerializedEditorState<SerializedLexicalNode> {
  return (
    typeof value === "object" &&
    value !== null &&
    "root" in value &&
    typeof (value as Record<string, unknown>).root === "object"
  );
}

export function fromLocalInputValue(value: string): string {
  if (!value) return "";
  try {
    const date = new Date(value);
    if (!isNaN(date.getTime())) {
      return date.toISOString();
    }
  } catch {
    // Ignore
  }
  return value;
}

export function toLocalInputValue(value: string): string {
  if (!value) return "";
  try {
    const date = new Date(value);
    if (!isNaN(date.getTime())) {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, "0");
      const day = String(date.getDate()).padStart(2, "0");
      const hours = String(date.getHours()).padStart(2, "0");
      const minutes = String(date.getMinutes()).padStart(2, "0");
      return `${year}-${month}-${day}T${hours}:${minutes}`;
    }
  } catch {
    // Ignore
  }
  return value;
}

const EMPTY_EDITOR_PARAGRAPHS: EditorParagraphNodeShape[] = [createParagraphNode()];
const EMPTY_EDITOR_STATE = createSerializedEditorState(EMPTY_EDITOR_PARAGRAPHS);

function createEditorStateFromPlainText(raw: string): SerializedEditorState {
  const lines = raw
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line, index, arr) => line !== "" || index < arr.length - 1);
  const paragraphs =
    lines.length > 0 ? lines.map((line) => createParagraphNode(line)) : EMPTY_EDITOR_PARAGRAPHS;

  return createSerializedEditorState(paragraphs);
}

export function normalizeContentForEditor(value: unknown): SerializedEditorState {
  if (isSerializedEditorState(value)) return value;
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed.startsWith("{")) {
      try {
        const parsed = JSON.parse(trimmed) as unknown;
        if (isSerializedEditorState(parsed)) {
          return parsed;
        }
      } catch {
        // Fallback to plain text import below.
      }
    }

    const plainText =
      typeof window !== "undefined" && /<[^>]+>/.test(value)
        ? new DOMParser().parseFromString(value, "text/html").body.textContent ?? value
        : value;
    return createEditorStateFromPlainText(plainText);
  }
  return EMPTY_EDITOR_STATE;
}

src/app/posts/_component/_form/post-form.content:
"use client"

import { LexicalEditor } from "@thangph2146/lexical-editor"
import { Badge } from "@ui/components/badge"
import {
  FieldError,
  FieldSet,
  FieldSetContent,
  FieldSectionLegend,
} from "@ui/components/field"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import { Switch } from "@ui/components/switch"
import { Textarea } from "@ui/components/textarea"
import { FormFieldCol, TreeMultiSelectInline } from "@ui/components/typing"
import { DatePicker } from "@ui/components/pickers"
import { cn } from "@ui/lib/utils"
import {
  AdminFormLayout,
  AdminFormMain,
  AdminFormPageHeader,
  AdminFormSidebar,
} from "@ui/components/admin"
import { Controller, type UseFormReturn } from "react-hook-form"
import {
  CalendarClock,
  FileText,
  Globe,
  ImageIcon,
  Search,
  Tags,
} from "lucide-react"
import { getSeoStatus, slugify as defaultSlugify } from "../utils"
import { PostImageField } from "./post-image-field"
import type { PostFormValues } from "../_hooks"
import type { CategoryTreeOption, TaxonomyOption } from "../types"

export interface PostFormShellProps {
  form: UseFormReturn<PostFormValues>
  onSubmit: (values: PostFormValues) => Promise<void>
  submitting: boolean
  editingId: string | null
  categoryTreeOptions: CategoryTreeOption[]
  tagsOptions: TaxonomyOption[]
  onBack: () => void
  onReset: () => void
}

export function PostFormShell({
  form,
  onSubmit,
  submitting,
  editingId,
  categoryTreeOptions,
  tagsOptions,
  onBack,
  onReset,
}: PostFormShellProps) {
  const { control, setValue, watch } = form

  const watchedTitle = watch("title")
  const watchedSlug = watch("slug")
  const watchedExcerpt = watch("excerpt")
  const watchedImage = watch("image") ?? ""

  const titleLength = watchedTitle.trim().length
  const excerptLength = watchedExcerpt.trim().length
  const normalizedSlug = watchedSlug.trim() || defaultSlugify(watchedTitle)
  const previewPath = normalizedSlug
    ? `/bai-viet/${normalizedSlug}`
    : "/bai-viet/ten-bai-viet"
  const titleSeo = getSeoStatus(titleLength, 30, 65)
  const excerptSeo = getSeoStatus(excerptLength, 70, 160)

  return (
    <>
      <AdminFormPageHeader
        title={editingId ? "Chỉnh sửa bài viết" : "Tạo bài viết mới"}
        subtitle="Quản lý bài viết và nội dung xuất bản."
        onBack={onBack}
        onReset={onReset}
        formId="post-form"
        submitting={submitting}
        isEdit={Boolean(editingId)}
      />

      <AdminFormLayout id="post-form" onSubmit={form.handleSubmit(onSubmit)}>
        <AdminFormMain>
          <FieldSet variant="section" className="overflow-visible">
            <FieldSectionLegend
              icon={FileText}
              title="Nội dung chi tiết"
              description="Nội dung phong phú cho bài viết (hỗ trợ rich text)."
            />
            <FieldSetContent variant="section" className="overflow-visible pt-0">
              <div className="mx-auto max-w-4xl overflow-visible">
                <Controller
                  name="content"
                  control={control}
                  render={({ field }) => (
                    <LexicalEditor
                      value={field.value}
                      placeholder="Nhập nội dung bài viết..."
                      onChange={(value) => field.onChange(value)}
                      uploadsContext={undefined}
                    />
                  )}
                />
              </div>
            </FieldSetContent>
          </FieldSet>
        </AdminFormMain>

        <AdminFormSidebar className="sticky top-2 max-h-[calc(100vh-80px)] overflow-y-auto">
          <FieldSet variant="section">
            <FieldSectionLegend
              icon={ImageIcon}
              title="Hình ảnh đại diện"
              description="Ảnh đại diện cho preview chia sẻ và danh sách bài viết."
            />
            <FieldSetContent variant="section" className="pt-0">
              <Controller
                name="image"
                control={control}
                render={({ field }) => (
                  <PostImageField
                    value={watchedImage || field.value || ""}
                    onChange={(url) => {
                      field.onChange(url)
                      setValue("image", url, {
                        shouldDirty: true,
                        shouldTouch: true,
                        shouldValidate: false,
                      })
                    }}
                    postTitle={watchedTitle}
                  />
                )}
              />
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={Search}
              title="Thông tin cơ bản"
              description="Tiêu đề, slug và mô tả ngắn — ảnh hưởng trực tiếp tới SEO."
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <Controller
                name="title"
                control={control}
                render={({ field, fieldState }) => (
                  <FormFieldCol label="Tiêu đề bài viết" required>
                    <Input
                      placeholder="VD: Thông báo tuyển sinh 2026"
                      {...field}
                      onChange={(e) => {
                        const { value } = e.target
                        field.onChange(value)
                        if (!editingId)
                          form.setValue("slug", defaultSlugify(value))
                      }}
                      className={cn(fieldState.error && "border-destructive")}
                    />
                    {fieldState.error && (
                      <FieldError>{fieldState.error.message}</FieldError>
                    )}
                    <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
                      <span>
                        Tiêu đề nên rõ chủ đề chính, dễ đọc và thu hút.
                      </span>
                      <Badge variant={titleSeo.tone} className="mt-1">
                        {titleLength} ký tự
                      </Badge>
                    </div>
                  </FormFieldCol>
                )}
              />

              <Controller
                name="slug"
                control={control}
                render={({ field }) => (
                  <FormFieldCol label="Slug / đường dẫn">
                    <Input
                      placeholder="thong-bao-tuyen-sinh-2026"
                      {...field}
                      onChange={(e) =>
                        field.onChange(defaultSlugify(e.target.value))
                      }
                    />
                    <div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground">
                      <Globe className="size-3 shrink-0" />
                      <span className="font-mono break-all">{previewPath}</span>
                    </div>
                  </FormFieldCol>
                )}
              />

              <Controller
                name="excerpt"
                control={control}
                render={({ field }) => (
                  <FormFieldCol label="Mô tả ngắn gọn">
                    <Textarea
                      placeholder="Đoạn mô tả ngắn để hiển thị danh sách..."
                      {...field}
                    />
                    <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
                      <span>Dùng làm mô tả tóm tắt và preview SEO.</span>
                      <Badge variant={excerptSeo.tone} className="mt-1">
                        {excerptLength} ký tự
                      </Badge>
                    </div>
                  </FormFieldCol>
                )}
              />

              <div className="rounded-lg border border-dashed border-primary/30 bg-primary/5 p-3">
                <p className="text-sm font-semibold text-foreground">
                  Preview kết quả tìm kiếm
                </p>
                <p className="mt-2 line-clamp-2 text-sm font-medium text-primary">
                  {watchedTitle.trim() ||
                    "Tiêu đề bài viết sẽ hiển thị tại đây"}
                </p>
                <p className="mt-1 text-xs break-all text-emerald-700 dark:text-emerald-400">
                  hub.local{previewPath}
                </p>
                <p className="mt-2 line-clamp-3 text-xs leading-5 text-muted-foreground">
                  {watchedExcerpt.trim() ||
                    "Mô tả ngắn của bài viết sẽ hiển thị ở đây để bạn kiểm tra cách trình bày SEO cơ bản."}
                </p>
              </div>
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={CalendarClock}
              title="Xuất bản"
              description="Trạng thái hiển thị và thời điểm phát hành bài viết."
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <Controller
                name="published"
                control={control}
                render={({ field }) => (
                  <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
                    <div>
                      <p className="text-sm font-medium">Trạng thái hiển thị</p>
                      <p className="text-xs text-muted-foreground">
                        {field.value
                          ? "Bài viết đang ở chế độ xuất bản."
                          : "Bài viết đang là bản nháp, chưa hiển thị công khai."}
                      </p>
                    </div>
                    <Switch
                      checked={field.value}
                      onCheckedChange={(checked) => field.onChange(checked)}
                    />
                  </div>
                )}
              />

              <Controller
                name="publishedAt"
                control={control}
                render={({ field }) => (
                  <FormFieldCol label="Ngày xuất bản">
                    <DatePicker
                      value={field.value}
                      onChange={(v) => field.onChange(v ?? "")}
                      placeholder="Chọn ngày"
                    />
                  </FormFieldCol>
                )}
              />
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={Tags}
              title="Phân loại"
              description="Gắn danh mục và thẻ để bài viết dễ tìm hơn."
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <Controller
                name="categoryIds"
                control={control}
                render={({ field }) => (
                  <FormFieldCol
                    label={
                      <div className="flex items-center justify-between gap-2">
                        <Label>Danh mục dùng chung</Label>
                        <Badge variant="outline">
                          {field.value.length} mục
                        </Badge>
                      </div>
                    }
                  >
                    <div className="rounded-lg border border-border/70 p-3">
                      <p className="mb-3 text-xs text-muted-foreground">
                        Danh mục theo cấu trúc cha-con.
                      </p>
                      <TreeMultiSelectInline
                        value={field.value}
                        onChange={(v) => field.onChange((v as string[]) ?? [])}
                        options={categoryTreeOptions.map((c) => ({
                          value: c.id,
                          label: c.name,
                          children: c.subRows?.map((s) => ({
                            value: s.id,
                            label: s.name,
                            children: s.subRows?.map((ss) => ({
                              value: ss.id,
                              label: ss.name,
                            })),
                          })),
                        }))}
                      />
                    </div>
                  </FormFieldCol>
                )}
              />
              <Controller
                name="tagIds"
                control={control}
                render={({ field }) => (
                  <FormFieldCol
                    label={
                      <div className="flex items-center justify-between gap-2">
                        <Label>Thẻ</Label>
                        <Badge variant="outline">
                          {field.value.length} thẻ
                        </Badge>
                      </div>
                    }
                  >
                    <div className="rounded-lg border border-border/70 p-3">
                      <TreeMultiSelectInline
                        value={field.value}
                        onChange={(v) => field.onChange((v as string[]) ?? [])}
                        options={(tagsOptions ?? []).map((t) => ({
                          value: t.id,
                          label: t.name,
                        }))}
                      />
                    </div>
                  </FormFieldCol>
                )}
              />
            </FieldSetContent>
          </FieldSet>
        </AdminFormSidebar>
      </AdminFormLayout>
    </>
  )
}

src/app/posts/_component/_form/post-imag.content:
"use client";

import { useRef, useState } from "react";
import { ImageIcon, ImagePlus, Loader2, X } from "lucide-react";
import { toast } from "@ui/components/sonner";
import { Input } from "@ui/components/input";
import { FormFieldCol } from "@ui/components/typing";
import { uploadPostImage } from "../utils";

type PostImageFieldProps = {
  value: string;
  onChange: (url: string) => void;
  postTitle?: string;
};

/** Upload + preview ảnh đại diện — cùng pattern với EventPosterField. */
export function PostImageField({ value, onChange, postTitle }: PostImageFieldProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const displayUrl = value.trim();

  const handleFile = async (file: File) => {
    setUploading(true);
    try {
      const url = await uploadPostImage(file);
      onChange(url);
      toast.success("Đã tải ảnh đại diện lên");
    } catch { /* toast: MutationCache */ } finally {
      setUploading(false);
    }
  };

  return (
    <FormFieldCol label="Hình ảnh đại diện">
      <div className="space-y-3">
        {displayUrl ? (
          <div className="relative overflow-hidden rounded-lg border border-border bg-muted/20">
            <img
              src={displayUrl}
              alt={postTitle?.trim() || "Ảnh đại diện bài viết"}
              className="aspect-[16/10] w-full object-cover"
            />
            <button
              type="button"
              onClick={() => onChange("")}
              className="absolute right-2 top-2 rounded-full bg-black/60 p-1.5 text-white hover:bg-black/80"
              aria-label="Xóa ảnh đại diện"
            >
              <X className="size-4" />
            </button>
          </div>
        ) : (
          <button
            type="button"
            disabled={uploading}
            onClick={() => inputRef.current?.click()}
            className="flex aspect-[16/10] w-full flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-border bg-muted/20 text-sm text-muted-foreground transition-colors hover:border-primary hover:text-primary disabled:opacity-60"
          >
            {uploading ? (
              <>
                <Loader2 className="size-6 animate-spin" />
                Đang tải ảnh…
              </>
            ) : (
              <>
                <ImagePlus className="size-6" />
                Chọn ảnh đại diện (16:10)
              </>
            )}
          </button>
        )}
        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          className="hidden"
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) void handleFile(file);
            e.target.value = "";
          }}
        />
        <div className="flex items-start gap-2 rounded-lg border border-dashed border-border/70 bg-muted/15 px-3 py-2 text-xs text-muted-foreground">
          <ImageIcon className="mt-0.5 size-3.5 shrink-0" />
          <span>
            Upload qua API (port 3002). URL hiển thị trực tiếp — cùng cách với poster sự kiện.
          </span>
