              { value: "/student/profile", label: "Hồ sơ sinh viên" },
            ],
          },
        ],
      },
    ],
    pages: HUB_CHECKIN_PAGES,
  },
]

export function getSettingsSeoPagesPresetGroup(
  id: string,
): SettingsSeoPagesPresetGroup | undefined {
  return SETTINGS_SEO_PAGES_PRESET_GROUPS.find((group) => group.id === id)
}

function findTreeNode(nodes: TreeOption[], value: string): TreeOption | null {
  for (const node of nodes) {
    if (node.value === value) return node
    if (node.children?.length) {
      const found = findTreeNode(node.children, value)
      if (found) return found
    }
  }
  return null
}

function collectLeafPagePaths(
  node: TreeOption,
  pageMap: Record<string, SettingsSeoPagePreset>,
): string[] {
  if (!node.children?.length) {
    return node.value in pageMap ? [node.value] : []
  }
  return node.children.flatMap((child) => collectLeafPagePaths(child, pageMap))
}

/** Đổ selection tree (gồm cả nhóm cha) thành danh sách `page` thực tế. */
export function resolveSettingsSeoPagesSelection(
  selected: string[],
  group: SettingsSeoPagesPresetGroup,
): string[] {
  const pages = new Set<string>()
  for (const value of selected) {
    if (value in group.pages) {
      pages.add(value)
      continue
    }
    const node = findTreeNode(group.tree, value)
    if (!node) continue
    for (const page of collectLeafPagePaths(node, group.pages)) {
      pages.add(page)
    }
  }
  return [...pages]
}

export function listAllPresetPagePaths(
  group: SettingsSeoPagesPresetGroup,
): string[] {
  return Object.keys(group.pages)
}

"use client"

import { useMemo, useState } from "react"
import { Loader2, ListChecks, ListX, Sparkles } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { Label } from "@ui/components/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs"
import { TreeMultiSelectInline } from "@ui/components/typing"
import { TypographyPSmallMuted } from "@ui/components/typography"
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell"
import { api } from "@/lib/api"
import { useAdminMutation } from "@/hooks/use-admin-mutation"
import {
  listAllPresetPagePaths,
  resolveSettingsSeoPagesSelection,
  SETTINGS_SEO_PAGES_PRESET_GROUPS,
} from "./settings-seo-pages-presets"

type SettingsSeoPagesQuickPresetsProps = {
  onApplied?: () => void | Promise<void>
  disabled?: boolean
}

export function SettingsSeoPagesQuickPresets({
  onApplied,
  disabled,
}: SettingsSeoPagesQuickPresetsProps) {
  const [activeGroupId, setActiveGroupId] = useState(
    SETTINGS_SEO_PAGES_PRESET_GROUPS[0]?.id ?? "hub-parent",
  )
  const [selected, setSelected] = useState<string[]>([])

  const activeGroup = useMemo(
    () =>
      SETTINGS_SEO_PAGES_PRESET_GROUPS.find(
        (group) => group.id === activeGroupId,
      ) ?? SETTINGS_SEO_PAGES_PRESET_GROUPS[0],
    [activeGroupId],
  )

  const resolvedPages = useMemo(() => {
    if (!activeGroup) return []
    return resolveSettingsSeoPagesSelection(selected, activeGroup)
  }, [activeGroup, selected])

  const applyMutation = useAdminMutation({
    toast: {
      loading: "Đang gắn SEO trang từ mẫu…",
      success: (data) =>
        `Đã gắn SEO cho ${Array.isArray(data) ? data.length : 0} trang`,
      error: "Không gắn được SEO trang từ mẫu",
    },
    mutationFn: async (pages: string[]) => {
      if (!activeGroup) return pages
      for (const page of pages) {
        const preset = activeGroup.pages[page]
        if (!preset) continue
        await api.seoMetas.upsertByPage({
          page: preset.page,
          title: preset.title,
          description: preset.description,
          keywords: preset.keywords,
          ogTitle: preset.ogTitle,
          ogDescription: preset.ogDescription,
          ogImage: preset.ogImage,
          status: 1,
        })
      }
      return pages
    },
    onSuccess: async () => {
      setSelected([])
      await onApplied?.()
    },
  })

  if (!activeGroup) return null

  return (
    <div className="space-y-4 rounded-lg border border-dashed border-border/80 bg-muted/30 p-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <Sparkles className="size-4 text-primary" aria-hidden />
            <Label className="text-sm font-medium">Gắn nhanh SEO theo trang</Label>
          </div>
          <TypographyPSmallMuted>
            Chọn trang trong cây route, bấm gắn để tạo/cập nhật metadata qua{" "}
            <code className="text-xs">PUT /admin/seo-metas/upsert</code>.
          </TypographyPSmallMuted>
        </div>
        <Badge variant="secondary" className="tabular-nums">
          {resolvedPages.length} trang
        </Badge>
      </div>

      <Tabs
        value={activeGroupId}
        onValueChange={(value) => {
          setActiveGroupId(value)
          setSelected([])
        }}
        className="space-y-3"
      >
        <TabsList className={ADMIN_LIST_TABS_LIST_CLASS}>
          {SETTINGS_SEO_PAGES_PRESET_GROUPS.map((group) => (
            <TabsTrigger
              key={group.id}
              value={group.id}
              className={ADMIN_LIST_TABS_TRIGGER_CLASS}
              title={group.hint}
            >
              {group.label}
            </TabsTrigger>
          ))}
        </TabsList>

        {SETTINGS_SEO_PAGES_PRESET_GROUPS.map((group) => (
          <TabsContent key={group.id} value={group.id} className="mt-0 space-y-3">
            <div className="flex flex-wrap gap-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                className="h-8 gap-1.5 rounded-lg text-xs"
                disabled={disabled || applyMutation.isPending}
                onClick={() =>
                  setSelected(listAllPresetPagePaths(group))
                }
              >
                <ListChecks className="size-3.5" aria-hidden />
                Chọn tất cả ({listAllPresetPagePaths(group).length})
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-8 gap-1.5 rounded-lg text-xs text-muted-foreground"
                disabled={
                  disabled || applyMutation.isPending || selected.length === 0
                }
                onClick={() => setSelected([])}
              >
                <ListX className="size-3.5" aria-hidden />
                Bỏ chọn
              </Button>
            </div>

            <div className="rounded-lg border bg-background p-2">
              <TreeMultiSelectInline
                value={selected}
                onChange={(value) =>
                  setSelected(Array.isArray(value) ? (value as string[]) : [])
                }
                options={group.tree}
              />
            </div>
          </TabsContent>
        ))}
      </Tabs>

      <div className="flex flex-wrap items-center justify-between gap-3 border-t pt-3">
        <TypographyPSmallMuted>
          Đường dẫn động dùng ký hiệu{" "}
          <code className="text-xs">[slug]</code> — storefront tra cứu theo pattern
          tương ứng.
        </TypographyPSmallMuted>
        <Button
          type="button"
          className="min-w-[10rem] rounded-lg"
          disabled={
            disabled || applyMutation.isPending || resolvedPages.length === 0
          }
          onClick={() => applyMutation.mutate(resolvedPages)}
        >
          {applyMutation.isPending ? (
            <Loader2 className="size-4 animate-spin" />
          ) : (
            <Sparkles className="size-4" />
          )}
          Gắn {resolvedPages.length || ""} trang
        </Button>
      </div>
    </div>
  )
}

"use client"

import { useEffect, useMemo, useState } from "react"
import type { ColumnDef, ColumnFiltersState, RowSelectionState } from "@tanstack/react-table"
import { useQueryClient } from "@tanstack/react-query"
import { AlertCircle, Plus } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs"
import { AdminPageHeaderPrimaryButton } from "@ui/components/admin"
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import { useDebouncedValue } from "@/hooks/use-debounced-value"
import { api } from "@/lib/api"
import { buildAdminFilterQuery, COMMON_FILTER_MAPPINGS } from "@/lib"
import { useAdminCrudRowHandlers } from "@/lib/admin-row-action-handlers"
import {
  getSeoMetaColumns,
  SeoMetasTable,
  useSeoMetasListQuery,
  useSeoMetasTrashQuery,
  prefetchSeoMetaDetail,
} from "@/app/seo-metas/_component"
import type { SeoMetaRow } from "@/app/seo-metas/_component"
import { useAdminMutation, defaultBulkOperationToast } from "@/hooks/use-admin-mutation"
import { SITE_SEO_PAGE_KEY } from "./constants"
import { SettingsSeoPagesQuickPresets } from "./settings-seo-pages-quick-presets"

export function SettingsSeoPagesSection({
  canWrite,
  canDelete,
  canRestore,
  canHardDelete,
  readOnlyHint,
}: {
  canWrite: boolean
  canDelete: boolean
  canRestore: boolean
  canHardDelete: boolean
  readOnlyHint?: React.ReactNode
}) {
  const queryClient = useQueryClient()
  const crudNav = useAdminCrudNavigation("/seo-metas", {
    prefetchDetail: (id) => prefetchSeoMetaDetail(queryClient, api, id),
  })

  const [mainTab, setMainTab] = useState<"list" | "trash">("list")
  const [globalFilter, setGlobalFilter] = useState("")
  const [trashPage, setTrashPage] = useState(1)
  const [trashPageSize] = useState(15)
  const [trashGlobalFilter, setTrashGlobalFilter] = useState("")
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
  const [trashColumnFilters, setTrashColumnFilters] =
    useState<ColumnFiltersState>([])
  const [listSelection, setListSelection] = useState<RowSelectionState>({})
  const [trashSelection, setTrashSelection] = useState<RowSelectionState>({})

  const debouncedTrashQ = useDebouncedValue(trashGlobalFilter, 350)

  const listFilterParams = useMemo(
    () => buildAdminFilterQuery(columnFilters, COMMON_FILTER_MAPPINGS.seoMetas),
    [columnFilters],
  )
  const trashFilterParams = useMemo(
    () =>
      buildAdminFilterQuery(trashColumnFilters, COMMON_FILTER_MAPPINGS.seoMetas),
    [trashColumnFilters],
  )

  const listQuery = useSeoMetasListQuery(api, true, listFilterParams)
  const pageRows = useMemo(
    () =>
      (listQuery.data ?? []).filter((row) => row.page !== SITE_SEO_PAGE_KEY),
    [listQuery.data],
  )

  const trashQuery = useSeoMetasTrashQuery({
    api,
    trashPage,
    trashPageSize,
    debouncedTrashQ,
    enabled: mainTab === "trash" && canWrite,
    filters: trashFilterParams,
  })

  const invalidateAll = async () => {
    await queryClient.invalidateQueries({ queryKey: ["seo-metas"] })
  }

  const deleteMutation = useAdminMutation({
    mutationKey: ["seo-metas", "delete"],
    mutationFn: async (id: string) => api.seoMetas.remove(id),
    onSuccess: invalidateAll,
  })
  const restoreMutation = useAdminMutation({
    mutationKey: ["seo-metas", "restore"],
    mutationFn: async (id: string) => api.seoMetas.restore(id),
    onSuccess: invalidateAll,
  })
  const purgeMutation = useAdminMutation({
    mutationKey: ["seo-metas", "purge"],
    mutationFn: async (id: string) => api.seoMetas.purge(id),
    onSuccess: invalidateAll,
  })
  const bulkMutation = useAdminMutation({
    toast: defaultBulkOperationToast,
    mutationFn: async (input: {
      action: "delete" | "restore" | "hard-delete"
      ids: string[]
    }) => api.seoMetas.bulk(input),
    onSuccess: invalidateAll,
  })

  useEffect(() => {
    setTrashPage(1)
  }, [trashColumnFilters, debouncedTrashQ, trashPageSize])
  useEffect(() => {
    setListSelection({})
    setTrashSelection({})
  }, [mainTab])

  const rowActions = useAdminCrudRowHandlers<SeoMetaRow>({
    getRecordLabel: (row) => row.page,
    entityLabel: "SEO metadata",
    deleteMutation,
    restoreMutation,
    purgeMutation,
  })

  const columns = useMemo<ColumnDef<SeoMetaRow>[]>(
    () =>
      getSeoMetaColumns({
        view: "list",
        openDetail: (row) => crudNav.view(String(row.id)),
        openEdit: (row) => crudNav.edit(String(row.id)),
        rowActions,
        canWrite,
        canDelete,
        canHardDelete,
      }),
    [rowActions, crudNav, canWrite, canDelete, canHardDelete],
  )

  const trashColumns = useMemo<ColumnDef<SeoMetaRow>[]>(
    () =>
      getSeoMetaColumns({
        view: "trash",
        rowActions,
        canWrite,
        canRestore,
        canHardDelete,
      }),
    [rowActions, canWrite, canRestore, canHardDelete],
  )

  return (
    <div className="space-y-4">
      {canWrite ? (
        <SettingsSeoPagesQuickPresets
          disabled={bulkMutation.isPending}
          onApplied={invalidateAll}
        />
      ) : null}

      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-sm text-muted-foreground">
            Quản lý title, mô tả và Open Graph cho từng đường dẫn trang công
            khai.
          </p>
          {readOnlyHint}
        </div>
        {canWrite ? (
          <AdminPageHeaderPrimaryButton
            type="button"
            onClick={() => crudNav.new()}
          >
            <Plus className="size-5" aria-hidden />
            Thêm SEO trang
          </AdminPageHeaderPrimaryButton>
        ) : null}
      </div>

      <Tabs
        value={mainTab}
        onValueChange={(v) => {
          if (v === "list" || v === "trash") setMainTab(v)
        }}
        className="space-y-4"
      >
        <TabsList className={ADMIN_LIST_TABS_LIST_CLASS}>
          <TabsTrigger value="list" className={ADMIN_LIST_TABS_TRIGGER_CLASS}>
            Danh sách
            <Badge
              variant="secondary"
              className="px-1.5 py-0 text-[10px] tabular-nums"
            >
              {pageRows.length}
            </Badge>
          </TabsTrigger>
          {canWrite ? (
            <TabsTrigger value="trash" className={ADMIN_LIST_TABS_TRIGGER_CLASS}>
              Thùng rác
              <Badge
                variant="secondary"
                className="px-1.5 py-0 text-[10px] tabular-nums"
              >
                {trashQuery.data?.total ?? 0}
              </Badge>
            </TabsTrigger>
          ) : null}
        </TabsList>

        <TabsContent value="list" className="mt-0 space-y-4">
          {listQuery.error ? (
            <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-destructive">
              <div className="flex items-start gap-3">
                <AlertCircle className="mt-0.5 size-5 shrink-0" aria-hidden />
                <div>
                  <p className="font-semibold">Không tải được danh sách</p>
                  <p className="mt-1 text-sm opacity-90">
                    {listQuery.error.message}
                  </p>
                </div>
              </div>
            </div>
          ) : null}

          <SeoMetasTable
            onRowPrefetch={(row) => crudNav.prefetch(String(row.id))}
            data={pageRows}
            columns={columns}
            isLoading={listQuery.isLoading}
            columnFilters={columnFilters}
            onColumnFiltersChange={setColumnFilters}
            globalFilter={globalFilter}
            onGlobalFilterChange={setGlobalFilter}
            selectedRowIds={listSelection}
            onSelectedRowIdsChange={setListSelection}
            total={pageRows.length}
            onClearFilters={() => {
              setColumnFilters([])
              setGlobalFilter("")
            }}
            onBulkDelete={
              canDelete
                ? async (rows) => {
                    const ids = rows.map((r) => r.id)
                    if (!ids.length) return
                    await bulkMutation.mutateAsync({ action: "delete", ids })
                  }
                : undefined
            }
            onBulkPurge={
              canHardDelete
                ? async (rows) => {
                    const ids = rows.map((r) => r.id)
                    if (!ids.length) return
                    await bulkMutation.mutateAsync({
                      action: "hard-delete",
                      ids,
                    })
                  }
                : undefined
            }
          />
        </TabsContent>

        {canWrite ? (
          <TabsContent value="trash" className="mt-0 space-y-4">
            <SeoMetasTable
              data={trashQuery.data?.items ?? []}
              columns={trashColumns}
              isLoading={trashQuery.isLoading}
              columnFilters={trashColumnFilters}
              onColumnFiltersChange={setTrashColumnFilters}
              globalFilter={trashGlobalFilter}
              onGlobalFilterChange={setTrashGlobalFilter}
              selectedRowIds={trashSelection}
              onSelectedRowIdsChange={setTrashSelection}
              total={trashQuery.data?.total ?? 0}
              onClearFilters={() => {
                setTrashColumnFilters([])
                setTrashGlobalFilter("")
              }}
              onBulkRestore={
                canRestore
                  ? async (rows) => {
                      const ids = rows.map((r) => r.id)
                      if (!ids.length) return
                      await bulkMutation.mutateAsync({ action: "restore", ids })
                    }
                  : undefined
              }
              onBulkPurge={
                canHardDelete
                  ? async (rows) => {
                      const ids = rows.map((r) => r.id)
                      if (!ids.length) return
                      await bulkMutation.mutateAsync({
                        action: "hard-delete",
                        ids,
                      })
                    }
                  : undefined
              }
            />
          </TabsContent>
        ) : null}
      </Tabs>
    </div>
  )
}

