                <div className="flex w-full flex-col gap-4">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="text-2xl font-bold">{entity.name}</p>
                    {entity.status === 1 ? (
                      <Badge variant="default" className="rounded-full px-3 py-0.5 shadow-sm">
