      ),
    },
    defineAdminCreatedAtColumn<TrainingLevelRow>({ defaultHidden: true }),
    defineAdminUpdatedAtColumn<TrainingLevelRow>({ header: "Cập nhật" }),
  ]

  return buildAdminTableColumns({
